    source = result.get("source_artifacts") if isinstance(result.get("source_artifacts"), dict) else {}
    if source:
        lines.extend(["", "## Source Artifacts"])
        for key in sorted(source):
            if source.get(key):
                lines.append(f"- `{key}`: `{source[key]}`")

    lines.extend(
        [
            "",
            "## Approval Request Rule",
            f"- {result.get('approval_request_rule')}",
            "",
            "## Safety",
            f"- {result.get('safety_note')}",
            "",
        ]
    )
    return "\n".join(lines)


