def _approval_plan_markdown(plan: dict) -> str:
    lines = [
        "# Revit Operator North-Star Approval Plan",
        "",
        "DRAFT / NOT FOR PERMIT / REQUIRES PE REVIEW",
        "",
        f"- Read only: `{str(plan.get('read_only')).lower()}`",
        f"- may_call_update_goal: `{str(plan.get('completion_actions', {}).get('may_call_update_goal')).lower()}`",
        f"- completion_blocked: `{str(plan.get('blocker_summary', {}).get('completion_blocked')).lower()}`",
        f"- blocked_gap_count: `{plan.get('blocked_gap_count')}`",
        f"- blocked_gate_count: `{plan.get('blocked_gate_count')}`",
        f"- cleared_gap_count: `{plan.get('cleared_gap_count')}`",
        f"- autonomous_progress_available: `{str(plan.get('autonomous_progress_available')).lower()}`",
        f"- human_or_real_condition_required: `{str(plan.get('human_or_real_condition_required')).lower()}`",
        "- blocked_waiting_for_human_or_real_condition: "
        f"`{str(plan.get('blocked_waiting_for_human_or_real_condition')).lower()}`",
        f"- blocked_gap_ids: `{', '.join(map(str, plan.get('blocked_gap_ids') or []))}`",
    ]
    preflight = plan.get("approval_preflight_readiness")
    preflight_items: dict[str, dict] = {}
    preflight_freshness_guard: dict | None = None
    if isinstance(preflight, dict):
        preflight_path = preflight.get("path")
        if preflight_path:
            try:
                preflight_data = json.loads(Path(str(preflight_path)).read_text(encoding="utf-8"))
            except Exception:
                preflight_data = {}
            if isinstance(preflight_data, dict):
                preflight_items = {
                    str(item.get("id")): item
                    for item in preflight_data.get("items", [])
                    if isinstance(item, dict) and item.get("id")
                }
        lines.extend(["", "## Approval Preflight Readiness"])
        lines.append(f"- Available: `{str(preflight.get('available')).lower()}`")
        if preflight.get("status"):
            lines.append(f"- Status: `{preflight.get('status')}`")
        for key in [
            "ready_for_human_approval_count",
            "requires_state_change_count",
            "requires_prevalidation_count",
            "unsafe_preflight_count",
        ]:
            if key in preflight:
                lines.append(f"- {key}: `{preflight.get(key)}`")
        if preflight.get("path"):
            lines.append(f"- JSON: `{preflight.get('path')}`")
        if preflight.get("markdown_path"):
            lines.append(f"- Markdown: `{preflight.get('markdown_path')}`")
        if preflight.get("reason"):
            lines.append(f"- Reason: {preflight.get('reason')}")
        preflight_freshness_guard = _approval_preflight_freshness_guard(
            {"summary": preflight, "items_by_id": preflight_items}
        )
    lines.extend(["", "## Approval Items"])
    approval_items = plan.get("approval_items") or []
    if not approval_items:
        lines.append("- None.")
    for item in approval_items:
        packet = _packet_approval_item(
            item,
            preflight_items=preflight_items,
            preflight_freshness_guard=preflight_freshness_guard,
        )
        recommended = " recommended" if packet.get("recommended") else ""
        lines.append(
            f"- `{packet.get('id')}`{recommended}: `{packet.get('decision')}` / `{packet.get('risk')}`"
        )
        if packet.get("gap_ids"):
            lines.append(f"  Gap IDs: `{', '.join(map(str, packet['gap_ids']))}`")
        lines.append(f"  Expected effect: {packet.get('expected_effect') or 'Not recorded.'}")
        lines.append(f"  Currently executable: `{str(packet.get('currently_executable')).lower()}`")
        if packet.get("prevalidation_status"):
            lines.append(f"  Prevalidation: `{packet['prevalidation_status']}`")
        readiness = packet.get("approval_readiness") if isinstance(packet.get("approval_readiness"), dict) else {}
        if readiness:
            lines.append(f"  Approval readiness: `{readiness.get('status')}`")
            if readiness.get("reason"):
                lines.append(f"  Readiness reason: {readiness.get('reason')}")
        elif isinstance(preflight, dict):
            lines.append("  Approval readiness: `requires_preflight`")
            lines.append("  Readiness reason: Latest approval preflight does not contain this item.")
        if packet.get("blocked_effects"):
            lines.append(f"  Blocked effects: `{', '.join(map(str, packet['blocked_effects']))}`")
        freshness = packet.get("approval_freshness") if isinstance(packet.get("approval_freshness"), dict) else {}
        if freshness:
            lines.append(f"  Bound payload digest: `{freshness.get('bound_payload_digest')}`")
            if freshness.get("prevalidation_artifact"):
                lines.append(f"  Prevalidation artifact: `{freshness.get('prevalidation_artifact')}`")
            if freshness.get("prevalidation_source_task_id"):
                lines.append(f"  Prevalidation source task: `{freshness.get('prevalidation_source_task_id')}`")
            if freshness.get("freshness_rule"):
                lines.append(f"  Freshness rule: {freshness.get('freshness_rule')}")
        token = packet.get("approval_token")
        if token:
            lines.append(
                "  Verify token: "
                f"`{_powershell_command(['north-star-approval-verify', '--approval-token', token])}`"
            )
        if packet.get("required_human_approval_phrase"):
            lines.append(
                "  Required human approval phrase: "
                f"`{packet['required_human_approval_phrase']}`"
            )
            if packet.get("approval_phrase_expires_at_utc"):
                lines.append(
                    "  Approval phrase expires at: "
                    f"`{packet.get('approval_phrase_expires_at_utc')}`"
                )
            if packet.get("approval_preflight_remaining_seconds") is not None:
                lines.append(
                    "  Approval preflight remaining seconds: "
                    f"`{packet.get('approval_preflight_remaining_seconds')}`"
                )
            lines.append(
                "  Approval phrase execution authority: "
                f"`{str(packet.get('approval_phrase_execution_authority')).lower()}`"
            )
            if packet.get("approval_phrase_safety_note"):
                lines.append(
                    "  Approval phrase safety note: "
                    f"{packet.get('approval_phrase_safety_note')}"
                )
        elif packet.get("required_human_approval_phrase_withheld"):
            lines.append(
                "  Required human approval phrase withheld: "
                f"{packet.get('withheld_required_human_approval_phrase_reason') or 'Approval item is not ready.'}"
            )
        if packet.get("phrase_verify_powershell"):
            lines.append(f"  Verify phrase: `{packet['phrase_verify_powershell']}`")
        if packet.get("execution_preview_powershell"):
            lines.append(
                "  Preview separate execution command: "
                f"`{packet['execution_preview_powershell']}`"
            )
        dry_run = packet.get("dry_run_powershell")
        if dry_run:
            lines.append(f"  Dry run before approval: `{dry_run}`")
        command = packet.get("command") or []
        if command and packet.get("approval_ready_now") is True:
            lines.append(
                "  Execute only after explicit approval: "
                f"`{packet.get('execute_powershell') or _powershell_command(command)}`"
            )
        elif command:
            reason = (
                readiness.get("reason")
                if readiness
                else "Latest approval preflight has not marked this item ready."
            )
            lines.append(f"  Execute withheld: {reason}")
        elif packet.get("withheld_execute_command"):
            lines.append(
                "  Execute withheld: "
                f"{packet.get('withheld_reason') or 'Latest approval preflight has not marked this item ready.'}"
            )
        if packet.get("post_checks"):
            lines.append(f"  Post-checks: `{'; '.join(map(str, packet['post_checks']))}`")

    lines.extend(["", "## Manual Items"])
    manual_items = plan.get("manual_items") or []
    if not manual_items:
        lines.append("- None.")
    for item in manual_items:
        lines.append(f"- `{item.get('id')}`: {item.get('reason') or 'No reason recorded.'}")
        if item.get("precondition"):
            lines.append(f"  Precondition: {item['precondition']}")
        if item.get("post_checks"):
            lines.append(f"  Post-checks: `{'; '.join(map(str, item['post_checks']))}`")

    lines.extend(
        [
            "",
            "## Safety",
            f"- {plan.get('safety_note')}",
            "- This approval plan does not execute any command. Execution requires a separate explicit human-approved command.",
            "",
        ]
    )
    return "\n".join(lines)


def _approval_preflight_result_summary(result: dict) -> dict:
    keys = [
        "success",
        "status",
        "dry_run",
        "planned_only",
        "executable",
        "match_count",
        "matched_count",
        "target_count",
        "stop_reason",
        "error",
        "reason",
        "path",
        "markdown_path",
    ]
    summary = {key: result.get(key) for key in keys if key in result}
    for nested_key in ["policy", "risk_classification"]:
        nested = result.get(nested_key)
        if isinstance(nested, dict):
            summary[nested_key] = {
                key: nested.get(key)
                for key in ["decision", "risk", "reason"]
                if key in nested
            }
    return summary


def _approval_preflight_success(result: dict) -> bool:
    if result.get("success") is True:
        return True
    if result.get("error"):
        return False
    status = str(result.get("status") or "").lower()
    if status.startswith("blocked") or status in {"error", "failed"}:
        return False
    if result.get("dry_run") is True or result.get("planned_only") is True:
        return True
    if status in {"dry_run", "planned", "approval_required"}:
        return True
    return False


def _approval_preflight_readiness(
    *,
    item: dict,
    status: str,
    preflight_result: dict,
    unsafe_flags: list[str],
) -> dict:
    prevalidation = item.get("prevalidation") if isinstance(item.get("prevalidation"), dict) else {}
    prevalidation_status = str(prevalidation.get("status") or "")
    currently_executable = item.get("currently_executable", prevalidation.get("executable"))
    if unsafe_flags:
        return {
            "status": "blocked_unsafe_preflight",
            "ready_for_human_approval": False,
            "reason": "Dry-run command contains execution or approval-token flags.",
        }
    if prevalidation_status == "not_prevalidated":
        return {
            "status": "requires_prevalidation",
            "ready_for_human_approval": False,
            "reason": "A fresh exact-target prevalidation is required before requesting approval.",
        }
    if prevalidation_status == "not_currently_executable" or currently_executable is False:
        return {
            "status": "requires_ui_state_change",
            "ready_for_human_approval": False,
            "reason": "The UI target is not currently executable from the observed Revit state.",
        }
    if status == "planned_only":
        return {
            "status": "requires_preflight",
            "ready_for_human_approval": False,
            "reason": "The approval item has been planned but its dry-run has not been invoked.",
        }
    if not _approval_preflight_success(preflight_result):
        return {
            "status": "preflight_failed",
            "ready_for_human_approval": False,
            "reason": "The dry-run/preflight result did not pass.",
        }
    return {
        "status": "ready_for_human_approval",
        "ready_for_human_approval": True,
        "reason": "Dry-run/preflight passed and the approval item has current target evidence.",
    }


def _approval_preflight_markdown(preflight: dict) -> str:
    lines = [
        "# Revit Operator North-Star Approval Preflight",
        "",
        "DRAFT / NOT FOR PERMIT / REQUIRES PE REVIEW",
        "",
        f"- Status: `{preflight.get('status')}`",
        f"- Read only: `{str(preflight.get('read_only')).lower()}`",
        f"- approval_item_count: `{preflight.get('approval_item_count')}`",
        f"- preflight_passed_count: `{preflight.get('preflight_passed_count')}`",
        f"- preflight_failed_count: `{preflight.get('preflight_failed_count')}`",
        f"- unsafe_preflight_count: `{preflight.get('unsafe_preflight_count')}`",
        f"- ready_for_human_approval_count: `{preflight.get('ready_for_human_approval_count')}`",
        f"- requires_state_change_count: `{preflight.get('requires_state_change_count')}`",
        f"- requires_prevalidation_count: `{preflight.get('requires_prevalidation_count')}`",
    ]
    expected_context = preflight.get("expected_context")
    if isinstance(expected_context, dict) and any(str(value or "") for value in expected_context.values()):
        lines.extend(
            [
                "",
                "## Expected Context",
                f"- Revit version: `{expected_context.get('revit_version')}`",
                f"- Expected title contains: `{expected_context.get('expected_title_contains') or ''}`",
                f"- Expected path contains: `{expected_context.get('expected_path_contains') or ''}`",
                f"- Expected view name: `{expected_context.get('expected_view_name') or ''}`",
                f"- Expected view type: `{expected_context.get('expected_view_type') or ''}`",
                f"- Context guard note: {preflight.get('context_guard_note')}",
            ]
        )
    freshness = (
        preflight.get("approval_preflight_freshness")
        if isinstance(preflight.get("approval_preflight_freshness"), dict)
        else {}
    )
    if freshness:
        lines.extend(
            [
                "",
                "## Approval Preflight Freshness",
                f"- Generated at: `{freshness.get('generated_at_utc')}`",
                f"- Expires at: `{freshness.get('expires_at_utc')}`",
                f"- TTL seconds: `{freshness.get('ttl_seconds')}`",
                f"- Rule: {freshness.get('freshness_rule')}",
            ]
        )
    refresh = (
        preflight.get("post_preflight_handoff_refresh")
        if isinstance(preflight.get("post_preflight_handoff_refresh"), dict)
        else {}
    )
    if refresh:
        lines.extend(
            [
                "",
                "## Post-Preflight Handoff Refresh",
                f"- required: `{str(refresh.get('required')).lower()}`",
                f"- read_only: `{str(refresh.get('read_only')).lower()}`",
                f"- execution_command_included: `{str(refresh.get('execution_command_included')).lower()}`",
                f"- approval_token_included: `{str(refresh.get('approval_token_included')).lower()}`",
                f"- powershell: `{refresh.get('powershell')}`",
                f"- Reason: {refresh.get('reason')}",
            ]
        )
    lines.extend(["", "## Items"])
    items = preflight.get("items") or []
    if not items:
        lines.append("- None.")
    for item in items:
        lines.append(f"- `{item.get('id')}`: `{item.get('status')}`")
        lines.append(f"  Expected effect: {item.get('expected_effect') or 'Not recorded.'}")
        if item.get("prevalidation_status"):
            lines.append(f"  Prevalidation: `{item.get('prevalidation_status')}`")
        if "currently_executable_from_plan" in item:
            lines.append(
                "  Currently executable from plan: "
                f"`{str(item.get('currently_executable_from_plan')).lower()}`"
            )
        readiness = item.get("approval_readiness") if isinstance(item.get("approval_readiness"), dict) else {}
        if readiness:
            lines.append(f"  Approval readiness: `{readiness.get('status')}`")
            if readiness.get("reason"):
                lines.append(f"  Readiness reason: {readiness.get('reason')}")
        if item.get("dry_run_powershell"):
            lines.append(f"  Dry run: `{item['dry_run_powershell']}`")
        if item.get("execute_powershell"):
            lines.append(f"  Execute only after explicit approval: `{item['execute_powershell']}`")
        elif item.get("execute_powershell_withheld"):
            lines.append(
                "  Execute withheld: "
                f"{item.get('withheld_reason') or 'Approval preflight artifacts are dry-run only.'}"
            )
        summary = item.get("preflight_summary") or {}
        if summary:
            lines.append(f"  Preflight summary: `{json.dumps(summary, sort_keys=True)}`")
        if item.get("unsafe_flags"):
            lines.append(f"  Unsafe flags: `{', '.join(map(str, item['unsafe_flags']))}`")

    lines.extend(
        [
            "",
            "## Safety",
            f"- {preflight.get('safety_note')}",
            "",
        ]
    )
    return "\n".join(lines)


def _packet_manual_item(item: dict) -> dict:
    return {
        "id": item.get("id"),
        "human_only": bool(item.get("human_only")),
        "reason": item.get("reason"),
        "precondition": item.get("precondition"),
        "post_checks": item.get("post_checks") or [],
    }


def _blocked_gap_ids(gap_evidence: list[dict]) -> set[str]:
    return {
        str(item.get("id"))
        for item in gap_evidence
        if isinstance(item.get("blocker"), dict) and item["blocker"].get("blocked") is True
    }


def _filter_plan_items_for_blocked_gaps(items: list[dict], blocked_gap_ids: set[str]) -> list[dict]:
    filtered = []
    for item in items:
        gap_ids = {str(gap_id) for gap_id in item.get("gap_ids") or []}
        if gap_ids and gap_ids.isdisjoint(blocked_gap_ids):
            continue
        filtered.append(item)
    return filtered


def _packet_manual_artifacts(status: dict) -> list[dict]:
    artifacts = []
    for gap in status.get("remaining_gaps") or []:
        if not isinstance(gap, dict):
            continue
        if gap.get("id") != "bridge_restart_validation":
            continue
        checklist_path = gap.get("no_save_checklist_path")
        if checklist_path:
            artifacts.append(
                {
                    "id": "bridge-restart-no-save-checklist",
                    "gap_id": gap.get("id"),
                    "path": checklist_path,
                    "present": bool(gap.get("no_save_checklist_present")),
                    "reason": (
                        "Human restart/reload checklist for dirty copied-model sessions; "
                        "Hermes must not answer save/sync prompts."
                    ),
                }
            )
    return artifacts


def _packet_manual_completion_checklist(
    *,
    status: dict,
    approval_items: list[dict],
    manual_artifacts: list[dict],
    resume_command: list[str],
) -> list[dict]:
    remaining_by_id = {
        str(gap.get("id")): gap for gap in status.get("remaining_gaps") or [] if isinstance(gap, dict)
    }
    artifacts_by_id = {str(artifact.get("id")): artifact for artifact in manual_artifacts}
    approval_by_gap: dict[str, list[dict]] = {}
    for item in approval_items:
        for gap_id in item.get("gap_ids") or []:
            approval_by_gap.setdefault(str(gap_id), []).append(item)

    checklist: list[dict] = []
    if "bridge_restart_validation" in remaining_by_id:
        checklist.append(
            {
                "id": "complete-bridge-restart-validation",
                "gap_id": "bridge_restart_validation",
                "human_action": (
                    "Human safely restarts or reloads Revit for the copied local model without "
                    "saving, syncing, detaching, upgrading, or writing to a central/cloud path."
                ),
                "preconditions": [
                    "Use only the copied local model and sandbox.",
                    "Do not let Hermes answer save/sync/reload/restart prompts.",
                    "Follow the bridge restart no-save checklist.",
                ],
                "manual_artifacts": [
                    artifacts_by_id["bridge-restart-no-save-checklist"]
                ]
                if "bridge-restart-no-save-checklist" in artifacts_by_id
                else [],
                "post_checks": [
                    "verify-bridge-build reports status current",
                    "bridge-readiness reports ready_for_continuous_bridge true",
                    "bridge-post-restart-validation reports validation_passed true",
                    "north-star-audit no longer lists bridge_restart_validation as blocked",
                ],
                "resume_command": resume_command,
            }
        )

    if "live_ui_workflow_execution" in remaining_by_id:
        checklist.append(
            {
                "id": "complete-approved-ui-workflow-execution",
                "gap_id": "live_ui_workflow_execution",
                "human_action": (
                    "Human reviews the current approval packet and provides exact step-indexed "
                    "approval tokens for a low-impact live UI workflow."
                ),
                "approval_item_ids": [
                    item.get("id") for item in approval_by_gap.get("live_ui_workflow_execution", [])
                ],
                "preconditions": [
                    "Use only approval tokens from the latest packet.",
                    "Verify the exact current approval phrase before executing.",
                    "Run the approved execution preview and confirm it names only the intended separate command.",
                    "Do not approve Save, Sync, Detach, Upgrade, Delete, or ambiguous buttons.",
                    "Stop if the observed Revit state differs from the packet prevalidation.",
                ],
                "post_checks": [
                    "ui-execution-coverage-audit counts at least one approved-ui-workflow-step",
                    "north-star-audit no longer lists live_ui_workflow_execution as blocked",
                ],
                "resume_command": resume_command,
            }
        )

    if "live_recovery_drills" in remaining_by_id:
        checklist.append(
            {
                "id": "complete-real-recovery-drill",
                "gap_id": "live_recovery_drills",
                "human_action": (
                    "Wait for a real non-synthetic modal, stuck, busy, unknown, or hung Revit "
                    "condition, then capture recovery evidence without inducing destructive states."
                ),
                "preconditions": [
                    "Do not fabricate or intentionally create a destructive Revit failure.",
                    "Capture recovery only when the real UI state already requires attention.",
                ],
                "post_checks": [
                    "recovery-snapshot records a qualifying live recovery condition",
                    "plan-current-dialog-response records conservative recovery guidance if a dialog exists",
                    "north-star-audit no longer lists live_recovery_drills as blocked",
                ],
                "resume_command": resume_command,
            }
        )

    if "live_uia_ribbon_context_execution" in remaining_by_id:
        checklist.append(
            {
                "id": "complete-approved-uia-ribbon-context-execution",
                "gap_id": "live_uia_ribbon_context_execution",
                "human_action": (
                    "Human approves exact low-impact UIA, ribbon, and context-menu actions after "
                    "fresh prevalidation confirms one unambiguous target."
                ),
                "approval_item_ids": [
                    item.get("id")
                    for item in approval_by_gap.get("live_uia_ribbon_context_execution", [])
                ],
                "preconditions": [
                    "Each action must have a fresh exact approval token.",
                    "Each action must pass exact approval phrase verification and execution preview.",
                    "Each UI target must resolve to exactly one enabled non-destructive control.",
                    "Do not approve File, Save, Save As, Sync, Print, Export, Publish, Delete, or ambiguous context-menu items.",
                ],
                "post_checks": [
                    "ui-execution-coverage-audit counts uia-invoke, ribbon-action, context-menu-action, and context-menu-item surfaces",
                    "north-star-audit no longer lists live_uia_ribbon_context_execution as blocked",
                ],
                "resume_command": resume_command,
            }
        )

    return checklist


def _blocked_ledger_entries(
    *,
    status: dict,
    approval_items: list[dict],
    manual_completion_checklist: list[dict],
    resume_command: list[str],
) -> list[dict]:
    approvals_by_gap: dict[str, list[dict]] = {}
    for item in approval_items:
        for gap_id in item.get("gap_ids") or []:
            readiness = item.get("approval_readiness") if isinstance(item.get("approval_readiness"), dict) else {}
            ready_now = item.get("approval_ready_now")
            execute_command = item.get("command") or []
            intended_execute_command = execute_command or item.get("withheld_execute_command") or []
            execute_allowed = ready_now is True
            withheld_reason = (
                item.get("withheld_reason")
                or readiness.get("reason")
                or "Latest approval preflight does not mark this item ready for human approval."
            )
            approvals_by_gap.setdefault(str(gap_id), []).append(
                {
                    "id": item.get("id"),
                    "recommended": item.get("recommended"),
                    "approval_token": item.get("approval_token") if execute_allowed else None,
                    "approval_token_withheld": bool(not execute_allowed and item.get("approval_token")),
                    "withheld_approval_token_reason": withheld_reason
                    if not execute_allowed and item.get("approval_token")
                    else "",
                    "expected_effect": item.get("expected_effect"),
                    "blocked_effects": item.get("blocked_effects") or [],
                    "post_checks": item.get("post_checks") or [],
                    "currently_executable": item.get("currently_executable"),
                    "prevalidation_status": item.get("prevalidation_status"),
                    "approval_readiness": readiness or None,
                    "approval_ready_now": ready_now,
                    "latest_preflight": item.get("latest_preflight"),
                    "execute_command": execute_command if execute_allowed else [],
                    "execute_powershell": (
                        item.get("execute_powershell") or _powershell_command(execute_command)
                    )
                    if execute_allowed
                    else "",
                    "withheld_execute_command": _redacted_approval_command(intended_execute_command)
                    if not execute_allowed and intended_execute_command
                    else [],
                    "withheld_reason": withheld_reason if not execute_allowed else "",
                    "dry_run_command": item.get("dry_run_command")
                    or _approval_dry_run_command(intended_execute_command),
                    "dry_run_powershell": item.get("dry_run_powershell")
                    or _powershell_command(_approval_dry_run_command(intended_execute_command)),
                    "verify_command": item.get("verify_command") if execute_allowed else [],
                    "verify_powershell": item.get("verify_powershell") if execute_allowed else "",
                    "required_human_approval_phrase": item.get("required_human_approval_phrase")
                    if execute_allowed
                    else None,
                    "approval_phrase_expires_at_utc": item.get("approval_phrase_expires_at_utc")
                    if execute_allowed
                    else None,
                    "approval_preflight_remaining_seconds": item.get(
                        "approval_preflight_remaining_seconds"
                    )
                    if execute_allowed
                    else None,
                    "approval_phrase_execution_authority": False,
                    "approval_phrase_safety_note": item.get("approval_phrase_safety_note")
                    if execute_allowed
                    else "No usable approval phrase is exposed until a fresh preflight marks this item ready.",
                    "required_human_approval_phrase_withheld": bool(
                        not execute_allowed
                        and (
                            item.get("required_human_approval_phrase")
                            or item.get("required_human_approval_phrase_withheld")
                        )
                    ),
                    "withheld_required_human_approval_phrase_reason": withheld_reason
                    if not execute_allowed
                    and (
                        item.get("required_human_approval_phrase")
                        or item.get("required_human_approval_phrase_withheld")
                    )
                    else "",
                    "phrase_verify_command": item.get("phrase_verify_command") if execute_allowed else [],
                    "phrase_verify_powershell": item.get("phrase_verify_powershell") if execute_allowed else "",
                    "execution_preview_command": item.get("execution_preview_command")
                    if execute_allowed
                    else [],
                    "execution_preview_powershell": item.get("execution_preview_powershell")
                    if execute_allowed
                    else "",
                    "execution_preview_rule": item.get("execution_preview_rule") if execute_allowed else "",
                }
            )

    manual_by_gap = {
        str(item.get("gap_id")): item
        for item in manual_completion_checklist
        if isinstance(item, dict) and item.get("gap_id")
    }
    entries = []
    for gap in status.get("remaining_gaps") or []:
        if not isinstance(gap, dict):
            continue
        gap_id = str(gap.get("id") or "")
        entry = {
            "gap_id": gap_id,
            "description": gap.get("description"),
            "blocker_type": gap.get("blocker_type"),
            "autonomy_status": gap.get("autonomy_status"),
            "next_step": gap.get("next_step"),
            "approval_items": approvals_by_gap.get(gap_id, []),
            "manual_completion_step": manual_by_gap.get(gap_id),
            "resume_command": resume_command,
            "recheck_commands": [
                "north-star-status",
                "north-star-audit",
                "north-star-completion-gate",
            ],
        }
        for key in [
            "failed_checks",
            "requires_revit_restart_or_reload",
            "no_save_checklist_path",
            "no_save_checklist_present",
            "approved_ui_workflow_step_count",
            "surface_counts",
            "reason",
        ]:
            if key in gap:
                entry[key] = gap[key]
        entries.append(entry)
    return entries


def _blocked_ledger_markdown(ledger: dict) -> str:
    lines = [
        "# Revit Operator Blocked North-Star Ledger",
        "",
        "DRAFT / NOT FOR PERMIT / REQUIRES PE REVIEW",
        "",
        f"- Status: `{ledger.get('status')}`",
        f"- generated_at_utc: `{ledger.get('generated_at_utc')}`",
        f"- north_star_complete: `{str(ledger.get('north_star_complete')).lower()}`",
        f"- completion_allowed: `{str(ledger.get('completion_allowed')).lower()}`",
        f"- may_call_update_goal: `{str(ledger.get('may_call_update_goal')).lower()}`",
        f"- audit_completion_authorized: `{str(ledger.get('audit_completion_authorized')).lower()}`",
        f"- may_execute_from_this_result: `{str(ledger.get('may_execute_from_this_result')).lower()}`",
        f"- entry_count: `{ledger.get('entry_count')}`",
        f"- blocked_gap_count: `{ledger.get('blocked_gap_count')}`",
        f"- blocked_gate_count: `{ledger.get('blocked_gate_count')}`",
        f"- autonomous_progress_available: `{str(ledger.get('autonomous_progress_available')).lower()}`",
        f"- human_or_real_condition_required: `{str(ledger.get('human_or_real_condition_required')).lower()}`",
        "- blocked_waiting_for_human_or_real_condition: "
        f"`{str(ledger.get('blocked_waiting_for_human_or_real_condition')).lower()}`",
    ]
    blocked_gap_ids = ledger.get("blocked_gap_ids") or []
    if blocked_gap_ids:
        lines.extend(["", "## Blocked Gap IDs"])
        for gap_id in blocked_gap_ids:
            lines.append(f"- `{gap_id}`")
    preflight = ledger.get("approval_preflight_readiness")
    if isinstance(preflight, dict):
        lines.extend(["", "## Approval Preflight Readiness"])
        lines.append(f"- Available: `{str(preflight.get('available')).lower()}`")
        if preflight.get("status"):
            lines.append(f"- Status: `{preflight.get('status')}`")
        for key in [
            "ready_for_human_approval_count",
            "requires_state_change_count",
            "requires_prevalidation_count",
            "unsafe_preflight_count",
        ]:
            if key in preflight:
                lines.append(f"- {key}: `{preflight.get(key)}`")
        if preflight.get("path"):
            lines.append(f"- JSON: `{preflight.get('path')}`")
        if preflight.get("markdown_path"):
            lines.append(f"- Markdown: `{preflight.get('markdown_path')}`")
        if preflight.get("reason"):
            lines.append(f"- Reason: {preflight.get('reason')}")

    lines.extend(["", "## Blocked Gates"])
    entries = ledger.get("entries") or []
    if not entries:
        lines.append("- None.")
    for entry in entries:
        lines.extend(
            [
                f"- `{entry.get('gap_id')}`: {entry.get('description') or 'No description recorded.'}",
                f"  Blocker: `{entry.get('blocker_type')}` / `{entry.get('autonomy_status')}`",
                f"  Next step: {entry.get('next_step') or 'Not recorded.'}",
            ]
        )
        if entry.get("failed_checks"):
            lines.append(f"  Failed checks: `{', '.join(map(str, entry['failed_checks']))}`")
        if entry.get("reason"):
            lines.append(f"  Reason: {entry['reason']}")
        manual = entry.get("manual_completion_step") or {}
        if manual:
            lines.append(f"  Manual action: {manual.get('human_action') or 'Not recorded.'}")
        approvals = entry.get("approval_items") or []
        if approvals:
            approval_ids = [str(item.get("id")) for item in approvals if item.get("id")]
            lines.append(f"  Approval items: `{', '.join(approval_ids)}`")
            for approval in approvals:
                readiness = approval.get("approval_readiness") if isinstance(approval.get("approval_readiness"), dict) else {}
                if readiness:
                    lines.append(f"  Approval readiness `{approval.get('id')}`: `{readiness.get('status')}`")
                    if readiness.get("reason"):
                        lines.append(f"  Readiness reason `{approval.get('id')}`: {readiness.get('reason')}")
                verify = approval.get("verify_powershell")
                if verify:
                    lines.append(f"  Verify `{approval.get('id')}`: `{verify}`")
                phrase = approval.get("required_human_approval_phrase")
                if phrase:
                    lines.append(f"  Required phrase `{approval.get('id')}`: `{phrase}`")
                    if approval.get("approval_phrase_expires_at_utc"):
                        lines.append(
                            f"  Approval phrase `{approval.get('id')}` expires at: "
                            f"`{approval.get('approval_phrase_expires_at_utc')}`"
                        )
                    lines.append(
                        f"  Approval phrase `{approval.get('id')}` execution authority: "
                        f"`{str(approval.get('approval_phrase_execution_authority')).lower()}`"
                    )
                    lines.append(
                        f"  Approval phrase `{approval.get('id')}` provenance: "
                        f"{approval.get('approval_phrase_safety_note') or APPROVAL_PHRASE_PROVENANCE_NOTE}"
                    )
                elif approval.get("required_human_approval_phrase_withheld"):
                    lines.append(
                        f"  Required phrase `{approval.get('id')}` withheld: "
                        f"{approval.get('withheld_required_human_approval_phrase_reason') or 'Approval item is not ready.'}"
                    )
                phrase_verify = approval.get("phrase_verify_powershell")
                if phrase_verify:
                    lines.append(
                        f"  Verify phrase `{approval.get('id')}`: `{phrase_verify}`"
                    )
                preview = approval.get("execution_preview_powershell")
                if preview:
                    lines.append(
                        f"  Preview `{approval.get('id')}` separate command: `{preview}`"
                    )
                dry_run = approval.get("dry_run_powershell")
                if dry_run:
                    lines.append(f"  Dry run `{approval.get('id')}` before approval: `{dry_run}`")
                execute = approval.get("execute_powershell")
                if execute:
                    lines.append(
                        f"  Execute `{approval.get('id')}` only after explicit approval: "
                        f"`{execute}`"
                    )
                elif approval.get("withheld_execute_command"):
                    lines.append(
                        f"  Execute `{approval.get('id')}` withheld: "
                        f"{approval.get('withheld_reason') or 'Approval item is not ready.'}"
                    )
        rechecks = entry.get("recheck_commands") or []
        if rechecks:
            lines.append(f"  Recheck: `{'; '.join(map(str, rechecks))}`")

    lines.extend(
        [
            "",
            "## Completion Rule",
            f"- {ledger.get('completion_rule')}",
            "",
            "## Safety",
            f"- {ledger.get('safety_note')}",
            "",
        ]
    )
    return "\n".join(lines)


def _completion_gate_markdown(gate: dict) -> str:
    lines = [
        "# Revit Operator North-Star Completion Gate",
        "",
        "DRAFT / NOT FOR PERMIT / REQUIRES PE REVIEW",
        "",
        f"- Status: `{gate.get('status')}`",
        f"- generated_at_utc: `{gate.get('generated_at_utc')}`",
        f"- north_star_complete: `{str(gate.get('north_star_complete')).lower()}`",
        f"- completion_allowed: `{str(gate.get('completion_allowed')).lower()}`",
        f"- may_call_update_goal: `{str(gate.get('may_call_update_goal')).lower()}`",
        f"- audit_completion_authorized: `{str(gate.get('audit_completion_authorized')).lower()}`",
        f"- may_execute_from_this_result: `{str(gate.get('may_execute_from_this_result')).lower()}`",
        f"- unsatisfied_count: `{gate.get('unsatisfied_count')}`",
        f"- blocked_gap_count: `{gate.get('blocked_gap_count')}`",
        f"- blocked_gate_count: `{gate.get('blocked_gate_count')}`",
        f"- autonomous_progress_available: `{str(gate.get('autonomous_progress_available')).lower()}`",
        f"- human_or_real_condition_required: `{str(gate.get('human_or_real_condition_required')).lower()}`",
        "- blocked_waiting_for_human_or_real_condition: "
        f"`{str(gate.get('blocked_waiting_for_human_or_real_condition')).lower()}`",
        f"- safety_guard_violation_count: `{gate.get('safety_guard_violation_count')}`",
        "",
        "## Completion Audit Summary",
    ]
    summary = (
        gate.get("completion_audit_summary")
        if isinstance(gate.get("completion_audit_summary"), dict)
        else {}
    )
    if summary:
        objective = summary.get("objective_restatement")
        if objective:
            lines.append(f"- Objective: {objective}")
        for key in [
            "prompt_to_artifact_checklist_total_count",
            "prompt_to_artifact_checklist_satisfied_count",
            "prompt_to_artifact_checklist_unsatisfied_count",
            "prompt_to_artifact_checklist_required_count",
            "prompt_to_artifact_checklist_required_present_count",
            "prompt_to_artifact_checklist_required_missing_count",
            "unverified_or_blocked_requirement_count",
            "blocked_gap_count",
            "blocked_gate_count",
            "audit_completion_authorized",
            "autonomous_progress_available",
            "human_or_real_condition_required",
            "safety_guard_violation_count",
            "autonomous_action_count",
            "human_action_count",
            "real_condition_action_count",
        ]:
            if key in summary:
                lines.append(f"- {key}: `{summary.get(key)}`")
        if summary.get("audit_markdown_path"):
            lines.append(f"- Audit markdown: `{summary.get('audit_markdown_path')}`")
    else:
        lines.append("- No summary recorded.")
    unsatisfied = gate.get("unsatisfied_requirement_summaries") or []
    lines.extend(["", "## Unsatisfied Requirement Summaries"])
    if unsatisfied:
        for item in unsatisfied:
            if not isinstance(item, dict):
                continue
            lines.append(f"- `{item.get('id')}`: `{item.get('status')}`")
            if item.get("category"):
                lines.append(f"  Category: `{item.get('category')}`")
            if item.get("blocker_type"):
                lines.append(f"  Blocker: `{item.get('blocker_type')}`")
            if item.get("requirement"):
                lines.append(f"  Requirement: {item.get('requirement')}")
            if item.get("reason"):
                lines.append(f"  Reason: {item.get('reason')}")
            if item.get("blocked_gaps"):
                lines.append(f"  Blocked gaps: `{', '.join(map(str, item.get('blocked_gaps') or []))}`")
            if item.get("next_step"):
                lines.append(f"  Next step: {item.get('next_step')}")
    else:
        lines.append("- None.")
    lines.extend([
        "",
        "## Blocked Gap IDs",
    ])
    blocked = gate.get("blocked_gap_ids") or []
    if blocked:
        for gap_id in blocked:
            lines.append(f"- `{gap_id}`")
    else:
        lines.append("- None.")

    lines.extend(["", "## Blocked Gate Details"])
    details = gate.get("blocked_gate_details") or []
    if details:
        for item in details:
            if not isinstance(item, dict):
                continue
            lines.append(f"- `{item.get('id')}`: {item.get('description')}")
            if item.get("blocker_type") or item.get("autonomy_status"):
                lines.append(
                    f"  Blocker: `{item.get('blocker_type')}` / `{item.get('autonomy_status')}`"
                )
            if item.get("next_step"):
                lines.append(f"  Next step: {item.get('next_step')}")
            for key in [
                "requires_revit_restart_or_reload",
                "failed_checks",
                "no_save_checklist_path",
                "approved_ui_workflow_step_count",
                "surface_counts",
                "reason",
            ]:
                if key in item and item.get(key) not in (None, [], {}):
                    lines.append(f"  {key}: `{json.dumps(item.get(key), sort_keys=True)}`")
    else:
        lines.append("- None.")

    lines.extend(["", "## Follow-Up Actions"])
    followups = gate.get("followup_actions") or []
    if followups:
        for item in followups:
            if not isinstance(item, dict):
                continue
            lines.append(f"- `{item.get('gap_id')}`: {item.get('action')}")
            if item.get("freshness_rule"):
                lines.append(f"  Freshness: {item.get('freshness_rule')}")
            commands = item.get("commands") or []
            if commands:
                lines.append(f"  Commands: `{'; '.join(map(str, commands))}`")
    else:
        lines.append("- None.")

    waiting_state = gate.get("waiting_state_summary") or {}
    next_approval = gate.get("next_approval_summary") or {}
    lines.extend(["", "## Current Waiting State"])
    if waiting_state.get("available"):
        lines.append(f"- Status: `{waiting_state.get('status')}`")
        lines.append(
            "- blocked_waiting_for_human_or_real_condition: "
            f"`{str(waiting_state.get('blocked_waiting_for_human_or_real_condition')).lower()}`"
        )
        if waiting_state.get("next_approval_item_id"):
            lines.append(f"- next_approval_item_id: `{waiting_state.get('next_approval_item_id')}`")
        if waiting_state.get("required_human_approval_phrase"):
            lines.append(
                "- required_human_approval_phrase: "
                f"`{waiting_state.get('required_human_approval_phrase')}`"
            )
            if waiting_state.get("approval_phrase_expires_at_utc"):
                lines.append(
                    "- approval_phrase_expires_at_utc: "
                    f"`{waiting_state.get('approval_phrase_expires_at_utc')}`"
                )
            if waiting_state.get("approval_phrase_safety_note"):
                lines.append(
                    "- approval_phrase_safety_note: "
                    f"{waiting_state.get('approval_phrase_safety_note')}"
                )
            lines.append("- approval_phrase_execution_authority: `false`")
        if waiting_state.get("required_human_approval_phrase_withheld"):
            lines.append("- required_human_approval_phrase: `WITHHELD_UNTIL_PREFLIGHT_FRESH`")
            if waiting_state.get("withheld_required_human_approval_phrase_reason"):
                lines.append(
                    "- withheld_reason: "
                    f"{waiting_state.get('withheld_required_human_approval_phrase_reason')}"
                )
        if waiting_state.get("preflight_guard_source"):
            lines.append(
                f"- preflight_guard_source: `{waiting_state.get('preflight_guard_source')}`"
            )
        if "preflight_fresh_now" in waiting_state:
            lines.append(
                "- preflight_fresh_now: "
                f"`{str(waiting_state.get('preflight_fresh_now')).lower()}`"
            )
        lines.append(
            "- may_execute_from_waiting_state: "
            f"`{str(waiting_state.get('may_execute_from_waiting_state')).lower()}`"
        )
        if waiting_state.get("resume_script"):
            lines.append(f"- resume_script: `{waiting_state.get('resume_script')}`")
    else:
        lines.append(f"- Not available: {waiting_state.get('reason') or 'No waiting-state artifact found.'}")

    lines.extend(["", "## Current Next Approval"])
    if next_approval.get("available"):
        lines.append(f"- Status: `{next_approval.get('status')}`")
        if next_approval.get("selected_item_id"):
            lines.append(f"- selected_item_id: `{next_approval.get('selected_item_id')}`")
        if next_approval.get("selected_expected_effect"):
            lines.append(f"- selected_expected_effect: {next_approval.get('selected_expected_effect')}")
        lines.append(f"- ready_approval_count: `{next_approval.get('ready_approval_count')}`")
        lines.append(f"- withheld_approval_count: `{next_approval.get('withheld_approval_count')}`")
        lines.append(
            "- may_execute_from_this_result: "
            f"`{str(next_approval.get('may_execute_from_this_result')).lower()}`"
        )
    else:
        lines.append(f"- Not available: {next_approval.get('reason') or 'No next-approval artifact found.'}")

    next_human = gate.get("next_human_action_summary") or {}
    lines.extend(["", "## Current Next Human Action"])
    if next_human.get("available"):
        lines.append(f"- Status: `{next_human.get('status')}`")
        lines.append(f"- option_count: `{next_human.get('option_count')}`")
        if next_human.get("approval_coverage_status"):
            lines.append(
                "- approval_coverage_status: "
                f"`{next_human.get('approval_coverage_status')}`"
            )
            lines.append(
                "- approval_coverage_violation_count: "
                f"`{next_human.get('approval_coverage_violation_count')}`"
            )
        option_ids = next_human.get("option_ids") or []
        if option_ids:
            lines.append(f"- option_ids: `{', '.join(map(str, option_ids))}`")
        option_summaries = [
            item
            for item in (next_human.get("option_summaries") or [])
            if isinstance(item, dict)
        ]
        for item in option_summaries:
            item_id = item.get("id")
            if not item_id:
                continue
            lines.append(f"- option `{item_id}`:")
            lines.append(f"  - kind: `{item.get('kind')}`")
            lines.append(
                "  - may_execute_from_this_option: "
                f"`{str(item.get('may_execute_from_this_option')).lower()}`"
            )
            if item_id == "human-restart-or-reload-revit":
                if item.get("title"):
                    lines.append(f"  - active_document: `{item.get('title')}`")
                if "dirty" in item:
                    lines.append(f"  - dirty: `{str(item.get('dirty')).lower()}`")
                if item.get("active_view_name") or item.get("active_view_type"):
                    lines.append(
                        "  - active_view: "
                        f"`{item.get('active_view_name') or ''} / {item.get('active_view_type') or ''}`"
                    )
                lines.append(
                    "  - dirty_state_warning_present: "
                    f"`{str(item.get('dirty_state_warning_present')).lower()}`"
                )
                if item.get("bridge_technical_cause"):
                    lines.append(
                        "  - bridge_technical_cause: "
                        f"{item.get('bridge_technical_cause')}"
                    )
                if item.get("failed_bridge_checks"):
                    lines.append(
                        "  - failed_bridge_checks: "
                        f"`{', '.join(map(str, item.get('failed_bridge_checks') or []))}`"
                    )
                if "requires_revit_restart_or_reload" in item:
                    lines.append(
                        "  - requires_revit_restart_or_reload: "
                        f"`{str(item.get('requires_revit_restart_or_reload')).lower()}`"
                    )
                if "no_save_checklist_present" in item:
                    lines.append(
                        "  - no_save_checklist_present: "
                        f"`{str(item.get('no_save_checklist_present')).lower()}`"
                    )
            elif item_id == "provide-exact-human-approval-phrase":
                if item.get("selected_item_id"):
                    lines.append(f"  - selected_item_id: `{item.get('selected_item_id')}`")
                if item.get("approval_blocker_gap_ids") is not None:
                    lines.append(
                        "  - approval_blocker_gap_ids: "
                        f"`{', '.join(map(str, item.get('approval_blocker_gap_ids') or []))}`"
                    )
                if item.get("selected_item_gap_ids") is not None:
                    lines.append(
                        "  - selected_item_gap_ids: "
                        f"`{', '.join(map(str, item.get('selected_item_gap_ids') or []))}`"
                    )
                if item.get("remaining_approval_gap_ids_after_selected_item") is not None:
                    lines.append(
                        "  - remaining_approval_gap_ids_after_selected_item: "
                        f"`{', '.join(map(str, item.get('remaining_approval_gap_ids_after_selected_item') or []))}`"
                    )
                if item.get("selected_item_covers_all_approval_blockers") is not None:
                    lines.append(
                        "  - selected_item_covers_all_approval_blockers: "
                        f"`{str(item.get('selected_item_covers_all_approval_blockers')).lower()}`"
                    )
                lines.append(
                    "  - approval_coverage_fields_present: "
                    f"`{str(item.get('approval_coverage_fields_present')).lower()}`"
                )
                lines.append(
                    "  - required_human_approval_phrase_withheld: "
                    f"`{str(item.get('required_human_approval_phrase_withheld')).lower()}`"
                )
                if item.get("preflight_guard_source"):
                    lines.append(
                        "  - preflight_guard_source: "
                        f"`{item.get('preflight_guard_source')}`"
                    )
                if item.get("approval_preflight_status"):
                    lines.append(
                        "  - approval_preflight_status: "
                        f"`{item.get('approval_preflight_status')}`"
                    )
                lines.append(
                    "  - preflight_fresh_now: "
                    f"`{str(item.get('preflight_fresh_now')).lower()}`"
                )
                lines.append(
                    "  - approval_preflight_command_present: "
                    f"`{str(item.get('approval_preflight_command_present')).lower()}`"
                )
                if item.get("approval_preflight_expires_at_utc"):
                    lines.append(
                        "  - approval_preflight_expires_at_utc: "
                        f"`{item.get('approval_preflight_expires_at_utc')}`"
                    )
                if item.get("approval_phrase_safety_note"):
                    lines.append(
                        "  - approval_phrase_safety_note: "
                        f"{item.get('approval_phrase_safety_note')}"
                    )
            elif item_id == "wait-for-real-recovery-condition":
                commands = item.get("safe_observation_commands") or []
                if commands:
                    lines.append(
                        "  - safe_observation_commands: "
                        f"`{', '.join(map(str, commands))}`"
                    )
        lines.append(
            "- may_execute_from_this_result: "
            f"`{str(next_human.get('may_execute_from_this_result')).lower()}`"
        )
        lines.append(
            "- execution_authority_violation: "
            f"`{str(next_human.get('execution_authority_violation')).lower()}`"
        )
        if next_human.get("markdown_path"):
            lines.append(f"- markdown: `{next_human.get('markdown_path')}`")
    else:
        lines.append(
            f"- Not available: {next_human.get('reason') or 'No next-human-action artifact found.'}"
        )

    packet = gate.get("supervised_command_packet") or {}
    lines.extend(["", "## Supervised Read-Only Command Packet"])
    if packet.get("available"):
        lines.append(f"- Status: `{packet.get('status')}`")
        lines.append(f"- May execute from this packet: `{str(packet.get('may_execute_from_this_packet')).lower()}`")
        lines.append(f"- Execution command included: `{str(packet.get('execution_command_included')).lower()}`")
        lines.append(
            "- Phrase must be supplied by human: "
            f"`{str(packet.get('phrase_must_be_supplied_by_human')).lower()}`"
        )
        lines.append(
            "- Auto-supplied phrase in commands: "
            f"`{str(packet.get('auto_supplied_phrase_in_commands')).lower()}`"
        )
        if packet.get("required_human_approval_phrase"):
            lines.append(
                "- Required human approval phrase: "
                f"`{packet.get('required_human_approval_phrase')}`"
            )
            if packet.get("approval_phrase_expires_at_utc"):
                lines.append(
                    "- Approval phrase expires at: "
                    f"`{packet.get('approval_phrase_expires_at_utc')}`"
                )
            if packet.get("approval_preflight_remaining_seconds") is not None:
                lines.append(
                    "- Approval preflight remaining seconds: "
                    f"`{packet.get('approval_preflight_remaining_seconds')}`"
                )
            lines.append("- Approval phrase execution authority: `false`")
        if packet.get("selected_item_id"):
            lines.append(f"- Selected item: `{packet.get('selected_item_id')}`")
        commands = packet.get("read_only_commands") if isinstance(packet.get("read_only_commands"), dict) else {}
        if commands:
            lines.append("- Read-only PowerShell sequence:")
            powershell = packet.get("read_only_powershell") or {}
            for key in [
                "approval_preflight",
                "approval_phrase_verify",
                "approved_execution_preview",
                "resume_check",
                "completion_gate",
            ]:
                if key in commands:
                    lines.append(f"  - `{key}`: `{powershell.get(key) or _powershell_command(commands[key])}`")
        if packet.get("freshness_rule"):
            lines.append(f"- Freshness: {packet.get('freshness_rule')}")
        if packet.get("safety_note"):
            lines.append(f"- Safety: {packet.get('safety_note')}")
    else:
        lines.append(f"- Not available: {packet.get('reason') or 'No supervised command packet available.'}")

    lines.extend(["", "## Safety Guard Violations"])
    violations = gate.get("safety_guard_violations") or []
    lines.append(f"- Count: `{gate.get('safety_guard_violation_count')}`")
    if violations:
        for item in violations:
            if not isinstance(item, dict):
                continue
            lines.append(f"- `{item.get('id')}`: {item.get('reason')}")
            if item.get("artifact"):
                lines.append(f"  Artifact: `{item.get('artifact')}`")
    else:
        lines.append("- None.")

    lines.extend(["", "## Safety Guard Follow-Up Actions"])
    safety_followups = gate.get("safety_guard_followup_actions") or []
    if safety_followups:
        for item in safety_followups:
            if not isinstance(item, dict):
                continue
            lines.append(f"- `{item.get('id')}`: {item.get('action')}")
            if item.get("freshness_rule"):
                lines.append(f"  Freshness: {item.get('freshness_rule')}")
            commands = item.get("commands") or []
            if commands:
                lines.append(f"  Commands: `{'; '.join(map(str, commands))}`")
    else:
        lines.append("- None.")

    lines.extend(["", "## Stable Artifacts To Open"])
    hints = gate.get("stable_artifact_hints") or []
    if hints:
        for item in hints:
            if not isinstance(item, dict):
                continue
            lines.append(
                f"- `{item.get('id')}` present: `{str(item.get('present')).lower()}`"
            )
            lines.append(f"  Purpose: {item.get('purpose')}")
            lines.append(f"  Path: `{item.get('path')}`")
    else:
        lines.append("- None recorded.")

    lines.extend(["", "## Blocked Reasons"])
    reasons = gate.get("blocked_reasons") or []
    if reasons:
        for reason in reasons:
            lines.append(f"- {reason}")
    else:
        lines.append("- None.")

    lines.extend(
        [
            "",
            "## Missing Counts",
            f"- `{json.dumps(gate.get('missing_counts') or {}, sort_keys=True)}`",
            "",
            "## Completion Rule",
            f"- {gate.get('completion_rule')}",
            "",
            "## Source Audit",
            f"- `{gate.get('audit_path')}`",
            "",
        ]
    )
    return "\n".join(lines)


def _unblock_current_artifact_summaries(sandbox: Path) -> dict[str, dict]:
    specs = {
        "status": "NORTH_STAR_STATUS_CURRENT.json",
        "audit": "NORTH_STAR_AUDIT_CURRENT.json",
        "completion_gate": "NORTH_STAR_COMPLETION_GATE_CURRENT.json",
        "handoff": "NORTH_STAR_HANDOFF_CURRENT.json",
        "blocked_ledger": "NORTH_STAR_BLOCKED_LEDGER_CURRENT.json",
        "human_gate_packet": "NORTH_STAR_HUMAN_GATE_PACKET_CURRENT.json",
        "next_human_action": "NORTH_STAR_NEXT_HUMAN_ACTION_CURRENT.json",
        "waiting_state": "NORTH_STAR_WAITING_STATE_CURRENT.json",
        "approval_preflight": "NORTH_STAR_APPROVAL_PREFLIGHT_CURRENT.json",
        "stable_artifact_scan": "NORTH_STAR_STABLE_ARTIFACT_SCAN_CURRENT.json",
    }
    return {
        key: _stable_json_artifact_summary(sandbox, filename)
        for key, filename in specs.items()
    }


def _stable_json_artifact_summary(sandbox: Path, filename: str) -> dict:
    path = sandbox / filename
    summary = {
        "available": False,
        "artifact": filename,
        "path": str(path),
    }
    if not path.exists():
        summary["reason"] = "Artifact is not present."
        return summary
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        summary["reason"] = f"Could not parse artifact: {type(exc).__name__}: {exc}"
        summary["json_parse_ok"] = False
        return summary
    if not isinstance(data, dict):
        summary["reason"] = f"Expected JSON object, got {type(data).__name__}."
        summary["json_parse_ok"] = False
        return summary

    summary["available"] = True
    summary["json_parse_ok"] = True
    for key in [
        "status",
        "north_star_complete",
        "completion_allowed",
        "may_call_update_goal",
        "may_execute_from_this_result",
        "audit_completion_authorized",
        "autonomous_progress_available",
        "human_or_real_condition_required",
        "blocked_waiting_for_human_or_real_condition",
        "blocked_gap_ids",
        "blocked_gap_count",
        "blocked_gate_count",
        "entry_count",
        "option_count",
        "option_ids",
        "option_summaries",
        "ready_approval_count",
        "withheld_approval_count",
        "violation_count",
        "credential_scan_mode",
        "deprecated",
        "redacted",
    ]:
        if key in data:
            summary[key] = data.get(key)
    return summary


def _unblock_readiness_packet(
    item: dict,
    *,
    artifact_readiness: dict,
    current_artifacts: dict[str, dict],
    preflight_freshness: dict,
) -> dict:
    gap_id = str(item.get("id") or "")
    blocker = item.get("blocker") if isinstance(item.get("blocker"), dict) else {}
    evidence = item.get("evidence") if isinstance(item.get("evidence"), dict) else {}
    evidence_summary = _unblock_evidence_summary(gap_id, evidence)
    blocker_type = blocker.get("type")
    approval_required = blocker_type == "human_approval_required"
    real_condition_required = blocker_type == "real_condition_required"
    human_action_required = blocker_type == "human_action_required"
    current_evidence_present = _unblock_evidence_present(evidence_summary)
    source_artifacts = _unblock_source_artifacts_for_gap(
        gap_id,
        artifact_readiness=artifact_readiness,
        current_artifacts=current_artifacts,
        evidence_summary=evidence_summary,
    )
    packet = {
        "gap_id": gap_id,
        "description": item.get("description"),
        "blocked": blocker.get("blocked") is True,
        "blocker_type": blocker_type,
        "autonomy_status": blocker.get("autonomy_status"),
        "current_evidence_present": current_evidence_present,
        "current_evidence_summary": evidence_summary,
        "source_artifacts": source_artifacts,
        "human_or_real_condition_required": bool(
            approval_required or real_condition_required or human_action_required
        ),
        "human_action_required": human_action_required,
        "human_approval_required": approval_required,
        "real_condition_required": real_condition_required,
        "autonomous_progress_available": blocker_type == "time_gated",
        "approval_preflight_fresh": preflight_freshness.get("matched") is True
        if approval_required
        else None,
        "approval_preflight_status": preflight_freshness.get("status")
        if approval_required
        else None,
        "required_human_action": blocker.get("next_step"),
        "completion_evidence_needed": UNBLOCK_COMPLETION_EVIDENCE.get(
            gap_id,
            "Fresh north-star-audit evidence must clear this gap.",
        ),
        "safe_next_commands": UNBLOCK_READINESS_COMMANDS.get(
            gap_id,
            ["north-star-status", "north-star-audit", "north-star-completion-gate"],
        ),
        "safe_supervision_refresh_command": artifact_readiness.get(
            "safe_supervision_refresh_command"
        ),
        "safe_supervision_refresh_powershell": artifact_readiness.get(
            "safe_supervision_refresh_powershell"
        ),
        "safe_supervision_refresh_context": artifact_readiness.get(
            "safe_supervision_refresh_context"
        ),
        "safe_supervision_refresh_read_only": artifact_readiness.get(
            "safe_supervision_refresh_read_only"
        )
        is True,
        "may_execute_from_this_result": False,
        "may_call_update_goal": False,
    }
    if gap_id == "bridge_restart_validation":
        packet["restart_no_save_checklist_present"] = artifact_readiness.get(
            "restart_no_save_checklist_present"
        )
        packet["restart_no_save_checklist_path"] = artifact_readiness.get(
            "restart_no_save_checklist_path"
        )
    if gap_id in {"live_ui_workflow_execution", "live_uia_ribbon_context_execution"}:
        packet["latest_ui_execution_coverage_present"] = artifact_readiness.get(
            "latest_ui_execution_coverage_present"
        )
        packet["latest_ui_execution_coverage_path"] = artifact_readiness.get(
            "latest_ui_execution_coverage_path"
        )
    if gap_id == "live_recovery_drills":
        packet["latest_recovery_evidence_present"] = artifact_readiness.get(
            "latest_recovery_evidence_present"
        )
        packet["latest_recovery_evidence_path"] = artifact_readiness.get(
            "latest_recovery_evidence_path"
        )
    return packet


def _unblock_evidence_summary(gap_id: str, evidence: dict) -> dict:
    if gap_id == "bridge_restart_validation":
        return {
            "available": evidence.get("available"),
            "ready_for_continuous_bridge": evidence.get("ready_for_continuous_bridge"),
            "requires_revit_restart_or_reload": evidence.get("requires_revit_restart_or_reload"),
            "status": evidence.get("status"),
            "failed_checks": evidence.get("failed_checks") or [],
            "restart_plan_artifact": evidence.get("restart_plan_artifact"),
            "no_save_checklist_path": evidence.get("no_save_checklist_path"),
            "no_save_checklist_present": evidence.get("no_save_checklist_present"),
            "restart_context": evidence.get("restart_context"),
            "error": evidence.get("error"),
        }
    if gap_id == "live_ui_workflow_execution":
        return {
            "artifact": evidence.get("artifact"),
            "approved_ui_workflow_step_count": evidence.get("approved_ui_workflow_step_count"),
            "target_met": evidence.get("target_met"),
        }
    if gap_id == "live_recovery_drills":
        return {
            "artifact": evidence.get("artifact"),
            "task_id": evidence.get("task_id"),
            "validated_live_recovery_drill": evidence.get("validated_live_recovery_drill"),
            "reason": evidence.get("reason"),
            "state": evidence.get("state"),
            "active_dialog_count": evidence.get("active_dialog_count"),
            "hung_window": evidence.get("hung_window"),
            "recommendation_classification": evidence.get("recommendation_classification"),
        }
    if gap_id == "supervision_endurance":
        return {
            "artifact": evidence.get("artifact"),
            "target_met": evidence.get("target_met"),
            "total_live_seconds": evidence.get("total_live_seconds"),
            "total_live_hours": evidence.get("total_live_hours"),
            "check_count": evidence.get("check_count"),
            "duration_remaining_seconds": evidence.get("duration_remaining_seconds"),
            "check_count_remaining": evidence.get("check_count_remaining"),
            "estimated_duration_target_at": evidence.get("estimated_duration_target_at"),
        }
    if gap_id == "live_uia_ribbon_context_execution":
        return {
            "artifact": evidence.get("artifact"),
            "uia_invoke_count": evidence.get("uia_invoke_count"),
            "ribbon_action_count": evidence.get("ribbon_action_count"),
            "context_menu_action_count": evidence.get("context_menu_action_count"),
            "context_menu_item_count": evidence.get("context_menu_item_count"),
        }
    return {
        key: value
        for key, value in evidence.items()
        if value not in (None, "", [], {})
    }


def _unblock_evidence_present(summary: dict) -> bool:
    for key, value in summary.items():
        if key in {"reason", "error"}:
            continue
        if value not in (None, "", [], {}, False):
            return True
    return False


def _unblock_source_artifacts_for_gap(
    gap_id: str,
    *,
    artifact_readiness: dict,
    current_artifacts: dict[str, dict],
    evidence_summary: dict,
) -> dict:
    common = {
        "completion_gate": current_artifacts["completion_gate"].get("path"),
        "blocked_ledger": current_artifacts["blocked_ledger"].get("path"),
        "next_human_action": current_artifacts["next_human_action"].get("path"),
        "stable_artifact_scan": current_artifacts["stable_artifact_scan"].get("path"),
    }
    if gap_id == "bridge_restart_validation":
        common.update(
            {
                "human_gate_packet": current_artifacts.get("human_gate_packet", {}).get("path"),
                "handoff": current_artifacts.get("handoff", {}).get("path"),
                "restart_plan_artifact": evidence_summary.get("restart_plan_artifact"),
                "no_save_checklist": evidence_summary.get("no_save_checklist_path")
                or artifact_readiness.get("restart_no_save_checklist_path"),
            }
        )
    elif gap_id in {"live_ui_workflow_execution", "live_uia_ribbon_context_execution"}:
        common.update(
            {
                "approval_preflight": current_artifacts["approval_preflight"].get("path"),
                "waiting_state": current_artifacts["waiting_state"].get("path"),
                "ui_execution_coverage": evidence_summary.get("artifact")
                or artifact_readiness.get("latest_ui_execution_coverage_path"),
            }
        )
    elif gap_id == "live_recovery_drills":
        common.update(
            {
                "recovery_evidence": evidence_summary.get("artifact")
                or artifact_readiness.get("latest_recovery_evidence_path"),
                "waiting_state": current_artifacts["waiting_state"].get("path"),
            }
        )
    elif gap_id == "supervision_endurance":
        common.update(
            {
                "supervision_endurance": evidence_summary.get("artifact")
                or artifact_readiness.get("latest_supervision_endurance_path"),
            }
        )
    return {key: value for key, value in common.items() if value}


def _unblock_readiness_markdown(readiness: dict) -> str:
    lines = [
        "# Revit Operator North-Star Unblock Readiness",
        "",
        "DRAFT / NOT FOR PERMIT / REQUIRES PE REVIEW",
        "",
        f"- Status: `{readiness.get('status')}`",
        f"- north_star_complete: `{str(readiness.get('north_star_complete')).lower()}`",
        f"- completion_allowed: `{str(readiness.get('completion_allowed')).lower()}`",
        f"- may_call_update_goal: `{str(readiness.get('may_call_update_goal')).lower()}`",
        f"- audit_completion_authorized: `{str(readiness.get('audit_completion_authorized')).lower()}`",
        f"- may_execute_from_this_result: `{str(readiness.get('may_execute_from_this_result')).lower()}`",
        f"- autonomous_progress_available: `{str(readiness.get('autonomous_progress_available')).lower()}`",
        f"- human_or_real_condition_required: `{str(readiness.get('human_or_real_condition_required')).lower()}`",
        "- blocked_waiting_for_human_or_real_condition: "
        f"`{str(readiness.get('blocked_waiting_for_human_or_real_condition')).lower()}`",
        f"- blocked_gap_count: `{readiness.get('blocked_gap_count')}`",
        f"- blocked_gate_count: `{readiness.get('blocked_gate_count')}`",
        f"- next_human_option_count: `{readiness.get('next_human_option_count')}`",
        f"- next_human_option_ids: `{', '.join(map(str, readiness.get('next_human_option_ids') or []))}`",
        "",
        "## Autonomous Stop",
    ]
    autonomous_stop = readiness.get("autonomous_stop") or {}
    lines.extend(
        [
            f"- active: `{str(autonomous_stop.get('active')).lower()}`",
            f"- status: `{autonomous_stop.get('status')}`",
            f"- reason: {autonomous_stop.get('reason')}",
            "- autonomous_progress_available: "
            f"`{str(autonomous_stop.get('autonomous_progress_available')).lower()}`",
            "- human_or_real_condition_required: "
            f"`{str(autonomous_stop.get('human_or_real_condition_required')).lower()}`",
            "- blocked_waiting_for_human_or_real_condition: "
            f"`{str(autonomous_stop.get('blocked_waiting_for_human_or_real_condition')).lower()}`",
            f"- may_call_update_goal: `{str(autonomous_stop.get('may_call_update_goal')).lower()}`",
            "- audit_completion_authorized: "
            f"`{str(autonomous_stop.get('audit_completion_authorized')).lower()}`",
            "- may_execute_from_this_result: "
            f"`{str(autonomous_stop.get('may_execute_from_this_result')).lower()}`",
            "- credential_material_included: "
            f"`{str(autonomous_stop.get('credential_material_included')).lower()}`",
            "- allowed_next_command_kinds: "
            f"`{', '.join(map(str, autonomous_stop.get('allowed_next_command_kinds') or []))}`",
            "- safe_refresh_read_only: "
            f"`{str(autonomous_stop.get('safe_refresh_read_only')).lower()}`",
        ]
    )
    if autonomous_stop.get("safe_refresh_command"):
        lines.append(
            "- safe_refresh_command: "
            f"`{' '.join(map(str, autonomous_stop.get('safe_refresh_command') or []))}`"
        )
    if autonomous_stop.get("forbidden_autonomous_action"):
        lines.append(
            f"- forbidden_autonomous_action: {autonomous_stop.get('forbidden_autonomous_action')}"
        )
    lines.extend(
        [
            "",
        "## Artifact Readiness",
        ]
    )
    artifact_readiness = readiness.get("artifact_readiness") or {}
    for key in sorted(artifact_readiness):
        value = artifact_readiness.get(key)
        if isinstance(value, (dict, list)):
            value = json.dumps(value, sort_keys=True)
        lines.append(f"- {key}: `{value}`")

    lines.extend(["", "## Blocker Packets"])
    packets = readiness.get("blocker_readiness") or []
    if not packets:
        lines.append("- None. Run `north-star-completion-gate` to verify completion authority.")
    for packet in packets:
        if not isinstance(packet, dict):
            continue
        lines.append(f"- `{packet.get('gap_id')}`: `{packet.get('autonomy_status')}`")
        lines.append(f"  Blocker: `{packet.get('blocker_type')}`")
        lines.append(
            "  current_evidence_present: "
            f"`{str(packet.get('current_evidence_present')).lower()}`"
        )
        lines.append(
            "  human_or_real_condition_required: "
            f"`{str(packet.get('human_or_real_condition_required')).lower()}`"
        )
        if packet.get("required_human_action"):
            lines.append(f"  Required action: {packet.get('required_human_action')}")
        if packet.get("completion_evidence_needed"):
            lines.append(f"  Completion evidence: {packet.get('completion_evidence_needed')}")
        commands = packet.get("safe_next_commands") or []
        if commands:
            lines.append(f"  Safe next commands: `{'; '.join(map(str, commands))}`")
        evidence = packet.get("current_evidence_summary") or {}
        if evidence:
            compact = {
                key: value
                for key, value in evidence.items()
                if value not in (None, "", [], {})
            }
            if compact:
                lines.append(f"  Evidence: `{json.dumps(compact, sort_keys=True)}`")

    option_summaries = [
        item
        for item in (readiness.get("next_human_option_summaries") or [])
        if isinstance(item, dict)
    ]
    lines.extend(["", "## Next Human Options"])
    if not option_summaries:
        lines.append("- None recorded. Open `NORTH_STAR_NEXT_HUMAN_ACTION_CURRENT.json`.")
    for item in option_summaries:
        lines.append(f"- `{item.get('id')}` / `{item.get('kind')}`")
        lines.append(
            "  may_execute_from_this_option: "
            f"`{str(item.get('may_execute_from_this_option')).lower()}`"
        )
        if item.get("gap_id"):
            lines.append(f"  gap_id: `{item.get('gap_id')}`")
        if item.get("approval_blocker_gap_ids"):
            lines.append(
                "  approval_blocker_gap_ids: "
                f"`{', '.join(map(str, item.get('approval_blocker_gap_ids') or []))}`"
            )
        if item.get("selected_item_id"):
            lines.append(f"  selected_item_id: `{item.get('selected_item_id')}`")
        if "preflight_fresh_now" in item:
            lines.append(
                "  preflight_fresh_now: "
                f"`{str(item.get('preflight_fresh_now')).lower()}`"
            )
        if item.get("safe_observation_commands"):
            lines.append(
                "  safe_observation_commands: "
                f"`{', '.join(map(str, item.get('safe_observation_commands') or []))}`"
            )

    lines.extend(
        [
            "",
            "## Completion Rule",
            f"- {readiness.get('completion_rule')}",
            "",
            "## Safety",
            f"- {readiness.get('safety_note')}",
            "",
        ]
    )
    return "\n".join(lines)


