def _restart_no_save_checklist_freshness_report(sandbox: Path) -> dict:
    artifact_name = "NORTH_STAR_BRIDGE_RESTART_NO_SAVE_CHECKLIST_CURRENT.md"
    source_artifact = "bridge_restart_validation_plan.json"
    next_human_artifact = "NORTH_STAR_NEXT_HUMAN_ACTION_CURRENT.json"
    checklist_path = sandbox / artifact_name
    next_human_path = sandbox / next_human_artifact
    source = _latest_json_artifact(sandbox, source_artifact)
    source_path_text = source.get("_artifact_path")
    result = {
        "status": "not_applicable",
        "artifact": artifact_name,
        "path": str(checklist_path),
        "present": checklist_path.exists(),
        "source_artifact": source_artifact,
        "source_path": source_path_text,
        "source_present": bool(source.get("available")),
        "next_human_artifact": next_human_artifact,
        "next_human_path": str(next_human_path),
        "next_human_present": next_human_path.exists(),
        "source_checklist_path": None,
        "source_checklist_present": None,
        "stable_checklist_mtime_utc": None,
        "source_plan_mtime_utc": None,
        "source_checklist_mtime_utc": None,
        "latest_source_mtime_utc": None,
        "tolerance_seconds": FRESH_PREFLIGHT_ALIGNMENT_TOLERANCE_SECONDS,
        "violations": [],
        "reason": (
            "No active stable restart option and latest bridge restart plan pair "
            "exists to compare against the no-save checklist."
        ),
    }
    if not next_human_path.exists():
        return result
    try:
        next_human = json.loads(next_human_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        result["status"] = "violations"
        result["reason"] = "Next-human-action JSON could not be read."
        result["violations"].append(
            {
                "id": "restart-checklist-freshness-next-human-unreadable",
                "artifact": next_human_artifact,
                "reason": (
                    "Stable next-human-action JSON could not be parsed for "
                    f"restart checklist freshness validation: {type(exc).__name__}: {exc}"
                ),
                "path": str(next_human_path),
            }
        )
        return result
    if not isinstance(next_human, dict):
        result["status"] = "violations"
        result["reason"] = "Next-human-action JSON is not an object."
        result["violations"].append(
            {
                "id": "restart-checklist-freshness-next-human-invalid",
                "artifact": next_human_artifact,
                "reason": "Stable next-human-action JSON is not a JSON object.",
                "path": str(next_human_path),
            }
        )
        return result
    restart_option_available = any(
        isinstance(option, dict)
        and option.get("id") == "human-restart-or-reload-revit"
        for option in (next_human.get("next_human_options") or [])
    )
    if not restart_option_available:
        result["reason"] = "No stable human restart/reload option exists."
        return result

    if source.get("error"):
        result["status"] = "violations"
        result["reason"] = "Latest bridge restart validation plan could not be read."
        result["violations"].append(
            {
                "id": "restart-checklist-freshness-source-unreadable",
                "artifact": source_artifact,
                "reason": (
                    "Latest bridge restart validation plan could not be parsed for "
                    f"restart checklist freshness validation: {source.get('error')}"
                ),
                "path": source_path_text,
            }
        )
        return result
    if not source.get("available"):
        result["reason"] = "No bridge restart validation plan exists."
        return result

    restart_required = (
        source.get("status") == "human_restart_required"
        or source.get("human_handoff_required") is True
        or source.get("restart_or_reload_required") is True
    )
    if not restart_required:
        result["reason"] = (
            "Latest bridge restart validation plan does not require a human restart/reload."
        )
        return result

    raw_source_checklist = str(source.get("no_save_checklist_path") or "").strip()
    if not raw_source_checklist:
        result["status"] = "violations"
        result["reason"] = "Latest bridge restart validation plan lacks a no-save checklist path."
        result["violations"].append(
            {
                "id": "restart-checklist-freshness-source-checklist-missing",
                "artifact": source_artifact,
                "reason": (
                    "Latest bridge restart validation plan requires human restart/reload "
                    "but does not expose no_save_checklist_path."
                ),
                "path": source_path_text,
            }
        )
        return result

    source_checklist_path = Path(raw_source_checklist)
    if not source_checklist_path.is_absolute():
        source_checklist_path = sandbox / source_checklist_path
    result["source_checklist_path"] = str(source_checklist_path)
    source_path = Path(source_path_text) if source_path_text else None
    source_plan_mtime = None
    source_checklist_mtime = None
    stable_mtime = None

    sandbox_error = validate_output_path(source_checklist_path, sandbox)
    if sandbox_error:
        result["status"] = "violations"
        result["reason"] = "Latest bridge restart validation plan references a checklist outside the sandbox."
        result["source_checklist_present"] = source_checklist_path.exists()
        result["violations"].append(
            {
                "id": "restart-checklist-freshness-source-checklist-outside-sandbox",
                "artifact": source_artifact,
                "reason": (
                    "Latest bridge restart validation plan references a no-save "
                    "checklist outside the sandbox."
                ),
                "path": str(source_checklist_path),
            }
        )
        return result
    if not source_checklist_path.exists():
        result["status"] = "violations"
        result["reason"] = "Latest bridge restart validation plan source checklist is missing."
        result["source_checklist_present"] = False
        result["violations"].append(
            {
                "id": "restart-checklist-freshness-source-checklist-missing-file",
                "artifact": source_artifact,
                "reason": (
                    "Latest bridge restart validation plan references a no-save "
                    "checklist that does not exist."
                ),
                "path": str(source_checklist_path),
            }
        )
        return result
    result["source_checklist_present"] = True
    if not checklist_path.exists():
        result["status"] = "violations"
        result["reason"] = "Stable bridge restart no-save checklist is missing."
        result["violations"].append(
            {
                "id": "restart-checklist-freshness-stable-missing",
                "artifact": artifact_name,
                "source_artifact": source_artifact,
                "reason": (
                    "Stable bridge restart no-save checklist is missing while the "
                    "latest bridge restart validation plan requires a human handoff."
                ),
                "path": str(checklist_path),
            }
        )
        return result

    try:
        stable_mtime = checklist_path.stat().st_mtime
        source_checklist_mtime = source_checklist_path.stat().st_mtime
        if source_path and source_path.exists():
            source_plan_mtime = source_path.stat().st_mtime
    except OSError as exc:
        result["status"] = "violations"
        result["reason"] = "Could not stat restart checklist freshness sources."
        result["violations"].append(
            {
                "id": "restart-checklist-freshness-stat-unavailable",
                "artifact": artifact_name,
                "source_artifact": source_artifact,
                "reason": (
                    "Could not stat stable/source restart checklist files for freshness "
                    f"validation: {type(exc).__name__}: {exc}"
                ),
                "path": str(checklist_path),
                "source_checklist_path": str(source_checklist_path),
                "source_path": source_path_text,
            }
        )
        return result

    latest_source_mtime = max(
        item for item in (source_plan_mtime, source_checklist_mtime) if item is not None
    )
    result["stable_checklist_mtime_utc"] = _format_unix_utc(stable_mtime)
    result["source_plan_mtime_utc"] = (
        _format_unix_utc(source_plan_mtime) if source_plan_mtime is not None else None
    )
    result["source_checklist_mtime_utc"] = _format_unix_utc(source_checklist_mtime)
    result["latest_source_mtime_utc"] = _format_unix_utc(latest_source_mtime)
    if stable_mtime + FRESH_PREFLIGHT_ALIGNMENT_TOLERANCE_SECONDS < latest_source_mtime:
        result["status"] = "violations"
        result["reason"] = (
            "Stable bridge restart no-save checklist is older than the latest "
            "bridge restart validation plan/checklist."
        )
        result["violations"].append(
            {
                "id": "restart-checklist-freshness-stale",
                "artifact": artifact_name,
                "source_artifact": source_artifact,
                "reason": (
                    "Stable bridge restart no-save checklist is older than the latest "
                    "bridge restart validation plan or its run-specific no-save checklist. "
                    "Regenerate the current handoff before asking the human to use it."
                ),
                "path": str(checklist_path),
                "source_path": source_path_text,
                "source_checklist_path": str(source_checklist_path),
                "stable_checklist_mtime_utc": result["stable_checklist_mtime_utc"],
                "source_plan_mtime_utc": result["source_plan_mtime_utc"],
                "source_checklist_mtime_utc": result["source_checklist_mtime_utc"],
                "tolerance_seconds": FRESH_PREFLIGHT_ALIGNMENT_TOLERANCE_SECONDS,
            }
        )
    else:
        result["status"] = "clean"
        result["reason"] = (
            "Stable bridge restart no-save checklist is fresh relative to the "
            "latest bridge restart validation plan/checklist."
        )
    return result


def _completion_gate_markdown_safety_count_report(sandbox: Path) -> dict:
    artifact_name = "NORTH_STAR_COMPLETION_GATE_CURRENT.md"
