def _latest_completion_mirror_report(
    sandbox: Path,
    *,
    artifact: str,
    label: str,
    violation_prefix: str,
) -> dict:
    payload = _latest_json_artifact(sandbox, artifact)
    result = {
        "status": "not_applicable",
        "available": payload.get("available") is True,
        "artifact": artifact,
        "path": payload.get("_artifact_path"),
        "label": label,
        "checked_fields": [
            "north_star_complete",
            "completion_allowed",
            "may_call_update_goal",
            "audit_completion_authorized",
            "blocked_gap_ids",
            "blocked_gap_count",
            "blocked_gate_count",
            "unsatisfied_count",
            "safety_guard_violation_count",
        ],
        "missing_top_level_fields": [],
        "missing_top_level_field_count": 0,
        "mismatches": [],
        "mismatch_count": 0,
        "violations": [],
        "reason": f"No {label} artifact is available.",
    }
    if payload.get("available") is not True:
        if payload.get("error"):
            result["status"] = "violations"
            result["reason"] = f"Latest {label} artifact could not be read."
            result["violations"].append(
                {
                    "id": f"{violation_prefix}-completion-mirror-unreadable",
                    "artifact": artifact,
                    "reason": (
                        f"Latest {label} artifact could not be parsed for "
                        f"completion mirror validation: {payload.get('error')}"
                    ),
                    "path": payload.get("_artifact_path"),
                }
            )
        return result

    gate = payload.get("completion_gate")
    if not isinstance(gate, dict):
        result["status"] = "violations"
        result["reason"] = f"Latest {label} artifact has no completion_gate object."
        result["violations"].append(
            {
                "id": f"{violation_prefix}-completion-gate-missing",
                "artifact": artifact,
                "reason": (
                    f"Latest {label} artifact cannot be trusted for "
                    "completion because it has no nested completion_gate object."
                ),
                "path": payload.get("_artifact_path"),
            }
        )
        return result

    expected = {
        "north_star_complete": gate.get("north_star_complete"),
        "completion_allowed": gate.get("completion_allowed"),
        "may_call_update_goal": gate.get("may_call_update_goal"),
        "audit_completion_authorized": gate.get("audit_completion_authorized"),
        "blocked_gap_ids": _stable_blocked_gap_ids(gate.get("blocked_gap_ids")),
        "blocked_gap_count": gate.get("blocked_gap_count"),
        "blocked_gate_count": gate.get("blocked_gate_count"),
        "unsatisfied_count": gate.get("unsatisfied_count"),
        "safety_guard_violation_count": len(gate.get("safety_guard_violations") or []),
    }
    missing_top_level = [
        field for field in result["checked_fields"] if field not in payload
    ]
    result["missing_top_level_fields"] = missing_top_level
    result["missing_top_level_field_count"] = len(missing_top_level)
    if missing_top_level:
        result["violations"].append(
            {
                "id": f"{violation_prefix}-top-level-completion-field-missing",
                "artifact": artifact,
                "reason": (
                    f"Latest {label} artifact is missing one or more "
                    "top-level completion-gate mirror fields."
                ),
                "missing_top_level_fields": missing_top_level,
                "path": payload.get("_artifact_path"),
            }
        )

    mismatches = []
    for field, expected_value in expected.items():
        if field not in payload:
            continue
        actual_value = payload.get(field)
        if field == "blocked_gap_ids":
            actual_value = _stable_blocked_gap_ids(actual_value)
            expected_value = _stable_blocked_gap_ids(expected_value)
        if actual_value != expected_value:
            mismatches.append(
                {
                    "field": field,
                    "top_level_value": actual_value,
                    "nested_completion_gate_value": expected_value,
                }
            )
    result["mismatches"] = mismatches
    result["mismatch_count"] = len(mismatches)
    if mismatches:
        result["violations"].append(
            {
                "id": f"{violation_prefix}-top-level-completion-field-mismatch",
                "artifact": artifact,
                "reason": (
                    f"Latest {label} top-level completion fields do not "
                    "mirror the nested hard completion gate."
                ),
                "mismatches": mismatches,
                "path": payload.get("_artifact_path"),
            }
        )

    if result["violations"]:
        result["status"] = "violations"
        result["reason"] = f"Latest {label} completion mirror violations were found."
    else:
        result["status"] = "clean"
        result["reason"] = (
            f"Latest {label} top-level completion fields mirror the "
            "nested hard completion gate."
        )
    return result


def _stable_current_artifact_inventory(sandbox: Path) -> list[dict]:
    inventory = []
    for path in sorted(sandbox.glob("NORTH_STAR_*CURRENT*"), key=lambda item: item.name):
        if not path.is_file():
            continue
        entry = {
            "artifact": path.name,
            "path": str(path),
            "size_bytes": None,
            "is_json": path.suffix.lower() == ".json",
            "json_parse_ok": None,
        }
        try:
            entry["size_bytes"] = path.stat().st_size
            if entry["is_json"]:
                json.loads(path.read_text(encoding="utf-8"))
                entry["json_parse_ok"] = True
        except (OSError, json.JSONDecodeError) as exc:
            entry["json_parse_ok"] = False if entry["is_json"] else None
            entry["read_error"] = f"{type(exc).__name__}: {exc}"
        inventory.append(entry)
    return inventory


def _stable_artifact_consistency_report(sandbox: Path) -> dict:
    fixed_artifact_names = [
        "NORTH_STAR_STATUS_CURRENT.json",
        "NORTH_STAR_AUDIT_CURRENT.json",
        "NORTH_STAR_COMPLETION_GATE_CURRENT.json",
        "NORTH_STAR_HANDOFF_CURRENT.json",
        "NORTH_STAR_BLOCKED_LEDGER_CURRENT.json",
        "NORTH_STAR_BLOCKED_HANDOFF_CURRENT.json",
        "NORTH_STAR_NEXT_HUMAN_ACTION_CURRENT.json",
        "NORTH_STAR_WAITING_STATE_CURRENT.json",
        "NORTH_STAR_APPROVAL_PREFLIGHT_CURRENT.json",
        "NORTH_STAR_STABLE_ARTIFACT_SCAN_CURRENT.json",
        "NORTH_STAR_UNBLOCK_READINESS_CURRENT.json",
        "NORTH_STAR_TRANSPORT_SAFETY_MATRIX_CURRENT.json",
    ]
    artifact_names: list[str] = []
    seen_artifact_names: set[str] = set()
    for artifact_name in fixed_artifact_names:
        artifact_names.append(artifact_name)
        seen_artifact_names.add(artifact_name)
    for path in sorted(sandbox.glob("NORTH_STAR_*CURRENT*.json"), key=lambda item: item.name):
        if path.is_file() and path.name not in seen_artifact_names:
            artifact_names.append(path.name)
            seen_artifact_names.add(path.name)
    summaries: list[dict] = []
    violations: list[dict] = []
    completion_gate_allowed = None
    completion_gate_blocked_gap_ids: list[str] | None = None
    completion_gate_path = sandbox / "NORTH_STAR_COMPLETION_GATE_CURRENT.json"
    if completion_gate_path.exists():
        try:
            completion_gate_data = json.loads(
                completion_gate_path.read_text(encoding="utf-8")
            )
            completion_gate_allowed = completion_gate_data.get("completion_allowed")
            completion_gate_blocked_gap_ids = _stable_blocked_gap_ids(
                completion_gate_data.get("blocked_gap_ids")
            )
        except (OSError, json.JSONDecodeError):
            completion_gate_allowed = None
            completion_gate_blocked_gap_ids = None

    for artifact_name in artifact_names:
        path = sandbox / artifact_name
        if not path.exists():
            summaries.append({"artifact": artifact_name, "present": False})
            continue
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError) as exc:
            summaries.append(
                {
                    "artifact": artifact_name,
                    "present": True,
                    "json_parse_ok": False,
                    "error": f"{type(exc).__name__}: {exc}",
                }
            )
            violations.append(
                {
                    "id": "stable-json-unreadable",
                    "artifact": artifact_name,
                    "reason": "Stable current JSON artifact could not be parsed.",
                }
            )
            continue
        summary = {
            "artifact": artifact_name,
            "present": True,
            "json_parse_ok": True,
            "status": data.get("status"),
            "north_star_complete": data.get("north_star_complete"),
            "completion_allowed": data.get("completion_allowed"),
            "may_call_update_goal": data.get("may_call_update_goal"),
            "audit_completion_authorized": data.get("audit_completion_authorized"),
            "blocked_gap_count": data.get("blocked_gap_count"),
            "blocked_gate_count": data.get("blocked_gate_count"),
            "deprecated": data.get("deprecated"),
            "redacted": data.get("redacted"),
        }
        safety_guard_count = data.get("safety_guard_violation_count")
        safety_guard_violations = data.get("safety_guard_violations")
        safety_guard_list_count = (
            len(safety_guard_violations)
            if isinstance(safety_guard_violations, list)
            else None
        )
        completion_summary = (
            data.get("completion_audit_summary")
            if isinstance(data.get("completion_audit_summary"), dict)
            else {}
        )
        summary_safety_guard_count = completion_summary.get(
            "safety_guard_violation_count"
        )
        if safety_guard_count is not None or safety_guard_list_count is not None:
            summary["safety_guard_violation_count"] = safety_guard_count
            summary["safety_guard_violation_list_count"] = safety_guard_list_count
            summary[
                "completion_audit_summary_safety_guard_violation_count"
            ] = summary_safety_guard_count
        artifact_blocked_gap_ids = _stable_blocked_gap_ids(data.get("blocked_gap_ids"))
        if artifact_blocked_gap_ids is not None:
            summary["blocked_gap_ids"] = artifact_blocked_gap_ids
            summary["blocked_gap_id_count"] = len(artifact_blocked_gap_ids)
        summaries.append(summary)
        if artifact_blocked_gap_ids is not None:
            count_values = {
                "blocked_gap_count": data.get("blocked_gap_count"),
                "blocked_gate_count": data.get("blocked_gate_count"),
            }
            for count_key, count_value in count_values.items():
                if count_value is None and artifact_blocked_gap_ids:
                    violations.append(
                        {
                            "id": "stable-blocker-count-missing",
                            "artifact": artifact_name,
                            "json_path": count_key,
                            "reason": (
                                "Stable current artifact lists blocked_gap_ids "
                                "but does not publish the corresponding blocker count."
                            ),
                            "blocked_gap_id_count": len(artifact_blocked_gap_ids),
                        }
                    )
                elif count_value is not None and count_value != len(artifact_blocked_gap_ids):
                    violations.append(
                        {
                            "id": "stable-blocker-count-id-mismatch",
                            "artifact": artifact_name,
                            "json_path": count_key,
                            "reason": (
                                "Stable current artifact blocker count does not match "
                                "its blocked_gap_ids length."
                            ),
                            "reported_count": count_value,
                            "blocked_gap_id_count": len(artifact_blocked_gap_ids),
                        }
                    )
            if (
                completion_gate_blocked_gap_ids is not None
                and artifact_name != "NORTH_STAR_COMPLETION_GATE_CURRENT.json"
                and sorted(artifact_blocked_gap_ids) != sorted(completion_gate_blocked_gap_ids)
            ):
                violations.append(
                    {
                        "id": "stable-blocker-id-mismatch",
                        "artifact": artifact_name,
                        "reason": (
                            "Stable current artifact blocked_gap_ids differ from the hard "
                            "completion gate."
                        ),
                        "artifact_blocked_gap_ids": artifact_blocked_gap_ids,
                        "completion_gate_blocked_gap_ids": completion_gate_blocked_gap_ids,
                    }
                )
        if (
            data.get("may_call_update_goal") is True
            and data.get("completion_allowed") is not True
        ):
            violations.append(
                {
                    "id": "goal-update-without-completion-allowed",
                    "artifact": artifact_name,
                    "reason": "Artifact allows update_goal without completion_allowed true.",
                }
                    )
        if (
            artifact_name == "NORTH_STAR_COMPLETION_GATE_CURRENT.json"
            and (
                data.get("completion_allowed") is True
                or data.get("may_call_update_goal") is True
            )
            and data.get("audit_completion_authorized") is not True
        ):
            violations.append(
                {
                    "id": "completion-gate-allowed-without-audit-authority",
                    "artifact": artifact_name,
                    "reason": (
                        "Published completion gate grants completion/update_goal "
                        "without audit_completion_authorized true."
                    ),
                    "completion_allowed": data.get("completion_allowed"),
                    "may_call_update_goal": data.get("may_call_update_goal"),
                    "audit_completion_authorized": data.get(
                        "audit_completion_authorized"
                    ),
                }
            )
        if safety_guard_count is not None or safety_guard_list_count is not None:
            if not isinstance(safety_guard_count, int):
                violations.append(
                    {
                        "id": "stable-safety-guard-count-invalid",
                        "artifact": artifact_name,
                        "json_path": "safety_guard_violation_count",
                        "reason": (
                            "Stable current artifact publishes safety guard metadata "
                            "without an integer safety_guard_violation_count."
                        ),
                        "reported_count": safety_guard_count,
                    }
                )
            if (
                isinstance(safety_guard_count, int)
                and safety_guard_list_count is not None
                and safety_guard_count != safety_guard_list_count
            ):
                violations.append(
                    {
                        "id": "stable-safety-guard-count-mismatch",
                        "artifact": artifact_name,
                        "json_path": "safety_guard_violation_count",
                        "reason": (
                            "Stable current artifact safety_guard_violation_count "
                            "does not match safety_guard_violations length."
                        ),
                        "reported_count": safety_guard_count,
                        "safety_guard_violation_list_count": safety_guard_list_count,
                    }
                )
            if (
                isinstance(safety_guard_count, int)
                and summary_safety_guard_count is not None
                and summary_safety_guard_count != safety_guard_count
            ):
                violations.append(
                    {
                        "id": "completion-gate-summary-safety-count-mismatch",
                        "artifact": artifact_name,
                        "json_path": "completion_audit_summary.safety_guard_violation_count",
                        "reason": (
                            "Completion audit summary safety guard count does not "
                            "match the top-level safety_guard_violation_count."
                        ),
                        "reported_count": summary_safety_guard_count,
                        "top_level_count": safety_guard_count,
                    }
                )
        if (
            completion_gate_allowed is False
            and artifact_name != "NORTH_STAR_COMPLETION_GATE_CURRENT.json"
            and data.get("completion_allowed") is True
        ):
            violations.append(
                {
                    "id": "artifact-completion-allowed-while-gate-blocked",
                    "artifact": artifact_name,
                    "reason": "Artifact grants completion while the hard gate is blocked.",
                }
            )
        if artifact_name == "NORTH_STAR_BLOCKED_HANDOFF_CURRENT.json":
            if data.get("deprecated") is not True or data.get("redacted") is not True:
                violations.append(
                    {
                        "id": "legacy-blocked-handoff-not-redacted",
                        "artifact": artifact_name,
                        "reason": "Legacy blocked handoff must be a deprecated redacted tombstone.",
                    }
                )
        for key_path, value in _walk_json_values(data):
            key = key_path[-1] if key_path else ""
            violation_reason = (
                _execution_authority_value_violation_reason(value)
                if _is_execution_authority_key(key)
                else ""
            )
            if violation_reason:
                violations.append(
                    {
                        "id": "stable-artifact-execution-authority",
                        "artifact": artifact_name,
                        "json_path": ".".join(key_path),
                        "reason": violation_reason,
                        "value_type": type(value).__name__,
                    }
                )
    return {"summaries": summaries, "violations": violations}


def _is_execution_authority_key(key: str) -> bool:
    normalized = key.lower()
    return (
        normalized.startswith("may_execute")
        or normalized
        in {
            "execution_by_this_command",
            "execution_command_included",
            "execution_authority_violation",
        }
    )


def _execution_authority_value_violation_reason(value: object) -> str:
    if value is False or value is None:
        return ""
    if value is True:
        return "Stable current artifact claims execution authority."
    return (
        "Stable current artifact has an execution-authority key whose value is "
        "not explicitly false or null."
    )


def _stable_artifact_preflight_alignment_report(
    sandbox: Path,
    *,
    freshness_guard: dict,
) -> dict:
    preflight_path = sandbox / "NORTH_STAR_APPROVAL_PREFLIGHT_CURRENT.json"
    fixed_artifact_names = [
        "NORTH_STAR_APPROVAL_PLAN_CURRENT.json",
        "NORTH_STAR_APPROVAL_PLAN_CURRENT.md",
        "NORTH_STAR_READY_APPROVALS_CURRENT.json",
        "NORTH_STAR_READY_APPROVALS_CURRENT.md",
        "NORTH_STAR_NEXT_APPROVAL_CURRENT.json",
        "NORTH_STAR_NEXT_APPROVAL_CURRENT.md",
        "NORTH_STAR_WAITING_STATE_CURRENT.json",
        "NORTH_STAR_WAITING_STATE_CURRENT.md",
        "NORTH_STAR_NEXT_HUMAN_ACTION_CURRENT.json",
        "NORTH_STAR_NEXT_HUMAN_ACTION_CURRENT.md",
        "NORTH_STAR_BLOCKED_LEDGER_CURRENT.json",
        "NORTH_STAR_BLOCKED_LEDGER_CURRENT.md",
        "NORTH_STAR_HUMAN_GATE_PACKET_CURRENT.json",
        "NORTH_STAR_HUMAN_GATE_PACKET_CURRENT.md",
        "NORTH_STAR_SUPERVISED_READONLY_CHECK_CURRENT.ps1",
        "NORTH_STAR_UNBLOCK_READINESS_CURRENT.json",
        "NORTH_STAR_UNBLOCK_READINESS_CURRENT.md",
        "NORTH_STAR_HANDOFF_CURRENT.json",
        "NORTH_STAR_HANDOFF_CURRENT.md",
        "NORTH_STAR_COMPLETION_GATE_CURRENT.json",
        "NORTH_STAR_COMPLETION_GATE_CURRENT.md",
    ]
    dynamic_exclusions = {
        "NORTH_STAR_APPROVAL_PREFLIGHT_CURRENT.json",
        "NORTH_STAR_APPROVAL_PREFLIGHT_CURRENT.md",
        "NORTH_STAR_STATUS_CURRENT.json",
        "NORTH_STAR_STATUS_CURRENT.md",
        "NORTH_STAR_AUDIT_CURRENT.json",
        "NORTH_STAR_AUDIT_CURRENT.md",
        "NORTH_STAR_STABLE_ARTIFACT_SCAN_CURRENT.json",
        "NORTH_STAR_STABLE_ARTIFACT_SCAN_CURRENT.md",
        "NORTH_STAR_TRANSPORT_SAFETY_MATRIX_CURRENT.json",
        "NORTH_STAR_TRANSPORT_SAFETY_MATRIX_CURRENT.md",
        "NORTH_STAR_BLOCKED_HANDOFF_CURRENT.json",
        "NORTH_STAR_BLOCKED_HANDOFF_CURRENT.md",
        "NORTH_STAR_BRIDGE_RESTART_NO_SAVE_CHECKLIST_CURRENT.md",
        "NORTH_STAR_POST_HUMAN_RESUME_CHECK_CURRENT.ps1",
    }
    artifact_names: list[str] = []
    seen_artifact_names: set[str] = set()
    for artifact_name in fixed_artifact_names:
        artifact_names.append(artifact_name)
        seen_artifact_names.add(artifact_name)
    for path in sorted(sandbox.glob("NORTH_STAR_*CURRENT*"), key=lambda item: item.name):
        if (
            path.is_file()
            and path.name not in seen_artifact_names
            and path.name not in dynamic_exclusions
        ):
            artifact_names.append(path.name)
            seen_artifact_names.add(path.name)
    result = {
        "status": "not_applicable",
        "reason": "Latest approval preflight is not fresh.",
        "preflight_path": str(preflight_path),
        "preflight_mtime_utc": None,
        "tolerance_seconds": FRESH_PREFLIGHT_ALIGNMENT_TOLERANCE_SECONDS,
        "checked_artifact_count": 0,
        "stale_artifact_count": 0,
        "summaries": [],
        "violations": [],
    }
    if freshness_guard.get("matched") is not True:
        return result
    if not preflight_path.exists():
        result["reason"] = "Freshness guard matched but stable approval preflight file is missing."
        result["violations"].append(
            {
                "id": "fresh-preflight-file-missing",
                "artifact": preflight_path.name,
                "reason": result["reason"],
                "path": str(preflight_path),
            }
        )
        result["status"] = "violations"
        return result

    try:
        preflight_mtime = preflight_path.stat().st_mtime
    except OSError as exc:
        result["reason"] = f"Could not stat stable approval preflight file: {type(exc).__name__}: {exc}"
        result["violations"].append(
            {
                "id": "fresh-preflight-file-unreadable",
                "artifact": preflight_path.name,
                "reason": result["reason"],
                "path": str(preflight_path),
            }
        )
        result["status"] = "violations"
        return result

    result["status"] = "aligned"
    result["reason"] = (
        "Latest approval preflight is fresh; existing approval-facing stable "
        "handoff artifacts must be at least as new as that preflight."
    )
    result["preflight_mtime_utc"] = _format_unix_utc(preflight_mtime)
    stale_count = 0
    for artifact_name in artifact_names:
        path = sandbox / artifact_name
        if not path.exists():
            result["summaries"].append({"artifact": artifact_name, "present": False})
            continue
        try:
            artifact_mtime = path.stat().st_mtime
        except OSError as exc:
            violation = {
                "id": "fresh-preflight-alignment-artifact-unreadable",
                "artifact": artifact_name,
                "reason": (
                    "Latest approval preflight is fresh, but this approval-facing "
                    f"stable artifact could not be inspected: {type(exc).__name__}: {exc}"
                ),
                "path": str(path),
            }
            result["violations"].append(violation)
            result["summaries"].append(
                {
                    "artifact": artifact_name,
                    "present": True,
                    "path": str(path),
                    "read_error": violation["reason"],
                }
            )
            continue
        older_than_preflight = (
            artifact_mtime + FRESH_PREFLIGHT_ALIGNMENT_TOLERANCE_SECONDS
            < preflight_mtime
        )
        result["checked_artifact_count"] += 1
        result["summaries"].append(
            {
                "artifact": artifact_name,
                "present": True,
                "path": str(path),
                "mtime_utc": _format_unix_utc(artifact_mtime),
                "older_than_preflight": older_than_preflight,
            }
        )
        if older_than_preflight:
            stale_count += 1
            result["violations"].append(
                {
                    "id": "fresh-preflight-stale-handoff-artifact",
                    "artifact": artifact_name,
                    "reason": (
                        "Latest approval preflight is fresh, but this approval-facing "
                        "stable handoff artifact is older than the current preflight. "
                        "Regenerate the current handoff before requesting or using "
                        "approval phrases."
                    ),
                    "path": str(path),
                    "artifact_mtime_utc": _format_unix_utc(artifact_mtime),
                    "preflight_mtime_utc": _format_unix_utc(preflight_mtime),
                    "tolerance_seconds": FRESH_PREFLIGHT_ALIGNMENT_TOLERANCE_SECONDS,
                }
            )
    result["stale_artifact_count"] = stale_count
    if result["violations"]:
        result["status"] = "violations"
    return result


def _stable_handoff_file_reference_report(sandbox: Path) -> dict:
    handoff_path = sandbox / "NORTH_STAR_HANDOFF_CURRENT.json"
    result = {
        "status": "not_available",
        "reason": "No stable current handoff JSON is present.",
        "handoff_path": str(handoff_path),
        "reference_count": 0,
        "present_count": 0,
        "missing_count": 0,
        "outside_sandbox_count": 0,
        "unreadable_json_count": 0,
        "references": [],
        "violations": [],
    }
    if not handoff_path.exists():
        return result

    try:
        handoff = json.loads(handoff_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        result["status"] = "violations"
        result["reason"] = "Stable current handoff JSON could not be parsed."
        result["violations"].append(
            {
                "id": "stable-handoff-unreadable",
                "artifact": handoff_path.name,
                "reason": f"Stable current handoff JSON could not be parsed: {type(exc).__name__}: {exc}",
                "path": str(handoff_path),
            }
        )
        return result

    stable_files = handoff.get("stable_files")
    if not isinstance(stable_files, dict) or not stable_files:
        result["status"] = "violations"
        result["reason"] = "Stable current handoff does not expose a stable_files map."
        result["violations"].append(
            {
                "id": "stable-handoff-stable-files-missing",
                "artifact": handoff_path.name,
                "reason": "Stable current handoff must expose a non-empty stable_files map.",
                "path": str(handoff_path),
            }
        )
        return result

    result["status"] = "ok"
    result["reason"] = "Stable current handoff file references are present and sandboxed."
    for key, raw_path in sorted(stable_files.items()):
        reference = {
            "key": str(key),
            "path": str(raw_path) if raw_path is not None else "",
            "inside_sandbox": None,
            "present": None,
            "json_parse_ok": None,
        }
        result["reference_count"] += 1
        if not isinstance(raw_path, str) or not raw_path.strip():
            reference["inside_sandbox"] = False
            reference["present"] = False
            result["missing_count"] += 1
            result["violations"].append(
                {
                    "id": "stable-handoff-reference-invalid",
                    "artifact": handoff_path.name,
                    "key": str(key),
                    "reason": "Stable handoff stable_files entry is not a non-empty path string.",
                }
            )
            result["references"].append(reference)
            continue

        ref_path = Path(raw_path)
        if not ref_path.is_absolute():
            ref_path = sandbox / ref_path
            reference["path"] = str(ref_path)
        sandbox_error = validate_output_path(ref_path, sandbox)
        if sandbox_error:
            reference["inside_sandbox"] = False
            reference["present"] = ref_path.exists()
            result["outside_sandbox_count"] += 1
            result["violations"].append(
                {
                    "id": "stable-handoff-reference-outside-sandbox",
                    "artifact": handoff_path.name,
                    "key": str(key),
                    "reason": "Stable handoff references a file outside the sandbox.",
                    "path": str(ref_path),
                }
            )
            result["references"].append(reference)
            continue

        reference["inside_sandbox"] = True
        reference["present"] = ref_path.exists()
        if not ref_path.exists():
            result["missing_count"] += 1
            result["violations"].append(
                {
                    "id": "stable-handoff-reference-missing",
                    "artifact": handoff_path.name,
                    "key": str(key),
                    "reason": "Stable handoff references a missing stable file.",
                    "path": str(ref_path),
                }
            )
            result["references"].append(reference)
            continue

        result["present_count"] += 1
        if ref_path.suffix.lower() == ".json":
            try:
                json.loads(ref_path.read_text(encoding="utf-8"))
                reference["json_parse_ok"] = True
            except (OSError, json.JSONDecodeError) as exc:
                reference["json_parse_ok"] = False
                result["unreadable_json_count"] += 1
                result["violations"].append(
                    {
                        "id": "stable-handoff-reference-json-unreadable",
                        "artifact": handoff_path.name,
                        "key": str(key),
                        "reason": (
                            "Stable handoff references a JSON file that could not be "
                            f"parsed: {type(exc).__name__}: {exc}"
                        ),
                        "path": str(ref_path),
                    }
                )
        result["references"].append(reference)

    if result["violations"]:
        result["status"] = "violations"
        result["reason"] = "Stable current handoff has broken stable file references."
    return result


def _stable_current_metadata_guard_report(sandbox: Path) -> dict:
    result = {
        "status": "not_available",
        "reason": "No stable current metadata artifacts are present.",
        "artifact_count": len(STABLE_CURRENT_METADATA_ARTIFACTS),
        "checked_artifact_count": 0,
        "missing_artifact_count": 0,
        "unreadable_artifact_count": 0,
        "invalid_artifact_count": 0,
        "missing_generated_at_count": 0,
        "read_only_drift_count": 0,
        "execution_authority_violation_count": 0,
        "summaries": [],
        "violations": [],
    }
    for artifact_name in STABLE_CURRENT_METADATA_ARTIFACTS:
        path = sandbox / artifact_name
        summary = {
            "artifact": artifact_name,
            "path": str(path),
            "present": path.exists(),
        }
        if not path.exists():
            result["missing_artifact_count"] += 1
            result["summaries"].append(summary)
            continue
        result["checked_artifact_count"] += 1
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError) as exc:
            result["unreadable_artifact_count"] += 1
            summary["json_parse_ok"] = False
            summary["error"] = f"{type(exc).__name__}: {exc}"
            result["violations"].append(
                {
                    "id": "stable-current-metadata-unreadable",
                    "artifact": artifact_name,
                    "path": str(path),
                    "reason": (
                        "Stable current metadata guard could not parse the JSON "
                        "artifact."
                    ),
                }
            )
            result["summaries"].append(summary)
            continue
        if not isinstance(data, dict):
            result["invalid_artifact_count"] += 1
            summary["json_parse_ok"] = True
            summary["object_json"] = False
            result["violations"].append(
                {
                    "id": "stable-current-metadata-invalid",
                    "artifact": artifact_name,
                    "path": str(path),
                    "reason": "Stable current metadata artifact is not a JSON object.",
                }
            )
            result["summaries"].append(summary)
            continue

        generated_at = data.get("generated_at_utc")
        read_only = data.get("read_only")
        may_execute = data.get("may_execute_from_this_result")
        summary.update(
            {
                "json_parse_ok": True,
                "object_json": True,
                "generated_at_utc": generated_at,
                "read_only": read_only,
                "may_execute_from_this_result": may_execute,
            }
        )
        if not isinstance(generated_at, str) or not generated_at.strip():
            result["missing_generated_at_count"] += 1
            result["violations"].append(
                {
                    "id": "stable-current-generated-at-missing",
                    "artifact": artifact_name,
                    "path": str(path),
                    "json_path": "generated_at_utc",
                    "reason": (
                        "Stable current handoff artifact must publish a "
                        "generated_at_utc timestamp for audit freshness."
                    ),
                }
            )
        if read_only is not True:
            result["read_only_drift_count"] += 1
            result["violations"].append(
                {
                    "id": "stable-current-readonly-drift",
                    "artifact": artifact_name,
                    "path": str(path),
                    "json_path": "read_only",
                    "reason": (
                        "Stable current handoff artifact must explicitly publish "
                        "read_only: true."
                    ),
                    "value": read_only,
                }
            )
        if may_execute is None:
            result["execution_authority_violation_count"] += 1
            result["violations"].append(
                {
                    "id": "stable-current-execution-authority-missing",
                    "artifact": artifact_name,
                    "path": str(path),
                    "json_path": "may_execute_from_this_result",
                    "reason": (
                        "Stable current handoff artifact must explicitly publish "
                        "may_execute_from_this_result: false."
                    ),
                }
            )
        elif may_execute is not False:
            result["execution_authority_violation_count"] += 1
            result["violations"].append(
                {
                    "id": "stable-current-execution-authority-drift",
                    "artifact": artifact_name,
                    "path": str(path),
                    "json_path": "may_execute_from_this_result",
                    "reason": (
                        "Stable current handoff artifact must not claim execution "
                        "authority."
                    ),
                    "value": may_execute,
                }
            )
        result["summaries"].append(summary)

    if result["violations"]:
        result["status"] = "violations"
        result["reason"] = "Stable current metadata has freshness or authority drift."
    elif result["checked_artifact_count"]:
        result["status"] = "ok"
        result["reason"] = (
            "Stable current metadata is timestamped, read-only, and non-executable."
        )
    return result


def _transport_safety_matrix_report(sandbox: Path) -> dict:
    json_path = sandbox / "NORTH_STAR_TRANSPORT_SAFETY_MATRIX_CURRENT.json"
    markdown_path = sandbox / "NORTH_STAR_TRANSPORT_SAFETY_MATRIX_CURRENT.md"
    result = {
        "status": "not_available",
        "reason": "No stable transport safety matrix artifact is present.",
        "artifact": json_path.name,
        "path": str(json_path),
        "markdown_artifact": markdown_path.name,
        "markdown_path": str(markdown_path),
        "json_present": json_path.exists(),
        "markdown_present": markdown_path.exists(),
        "json_parse_ok": None,
        "matrix_status": None,
        "check_count": None,
        "failed_count": None,
        "direct_approval_marker_count": None,
        "raw_approval_marker_count": 0,
        "field_drift_count": 0,
        "markdown_missing_line_count": 0,
        "violations": [],
    }
    if not json_path.exists() and not markdown_path.exists():
        return result
    if not json_path.exists():
        result["status"] = "violations"
        result["reason"] = "Transport safety matrix Markdown exists without JSON."
        result["field_drift_count"] = 1
        result["violations"].append(
            {
                "id": "transport-safety-matrix-json-missing",
                "artifact": json_path.name,
                "markdown_artifact": markdown_path.name,
                "reason": (
                    "Stable transport safety matrix Markdown is present, but the "
                    "machine-readable JSON artifact is missing."
                ),
                "path": str(json_path),
            }
        )
        return result

    try:
        raw_text = json_path.read_text(encoding="utf-8")
        data = json.loads(raw_text)
    except (OSError, json.JSONDecodeError) as exc:
        result["status"] = "violations"
        result["reason"] = "Transport safety matrix JSON could not be parsed."
        result["json_parse_ok"] = False
        result["field_drift_count"] = 1
        result["violations"].append(
            {
                "id": "transport-safety-matrix-unreadable",
                "artifact": json_path.name,
                "reason": (
                    "Stable transport safety matrix JSON could not be parsed: "
                    f"{type(exc).__name__}: {exc}"
                ),
                "path": str(json_path),
            }
        )
        return result
    if not isinstance(data, dict):
        result["status"] = "violations"
        result["reason"] = "Transport safety matrix JSON is not an object."
        result["json_parse_ok"] = True
        result["field_drift_count"] = 1
        result["violations"].append(
            {
                "id": "transport-safety-matrix-invalid",
                "artifact": json_path.name,
                "reason": "Stable transport safety matrix JSON is not a JSON object.",
                "path": str(json_path),
            }
        )
        return result

    result["json_parse_ok"] = True
    result["matrix_status"] = data.get("status")
    result["check_count"] = data.get("check_count")
    result["failed_count"] = data.get("failed_count")
    result["direct_approval_marker_count"] = data.get("direct_approval_marker_count")

    raw_marker_count = len(re.findall(r"\bAPPROVE:[A-Za-z0-9_.:-]+\b", raw_text)) + len(
        re.findall(r"\bI approve\b", raw_text, flags=re.IGNORECASE)
    )
    result["raw_approval_marker_count"] = raw_marker_count
    if raw_marker_count:
        result["field_drift_count"] += 1
        result["violations"].append(
            {
                "id": "transport-safety-matrix-raw-approval-marker-leak",
                "artifact": json_path.name,
                "reason": (
                    "Stable transport safety matrix JSON contains direct approval "
                    "markers; regenerate it after redaction hardening."
                ),
                "marker_count": raw_marker_count,
            }
        )

    exact_expectations = [
        ("status", "clean", "transport-safety-matrix-not-clean"),
        ("read_only", True, "transport-safety-matrix-readonly-drift"),
        ("live_revit_touched", False, "transport-safety-matrix-live-touch-drift"),
        (
            "may_execute_from_this_result",
            False,
            "transport-safety-matrix-execution-authority-drift",
        ),
        (
            "completion_allowed",
            False,
            "transport-safety-matrix-completion-authority-drift",
        ),
        (
            "may_call_update_goal",
            False,
            "transport-safety-matrix-goal-authority-drift",
        ),
        (
            "audit_completion_authorized",
            False,
            "transport-safety-matrix-audit-authority-drift",
        ),
        ("failed_count", 0, "transport-safety-matrix-failed-count-drift"),
        (
            "direct_approval_marker_count",
            0,
            "transport-safety-matrix-direct-approval-marker-drift",
        ),
    ]
    for key, expected, violation_id in exact_expectations:
        actual = data.get(key)
        if actual == expected and type(actual) is type(expected):
            continue
        result["field_drift_count"] += 1
        result["violations"].append(
            {
                "id": violation_id,
                "artifact": json_path.name,
                "json_path": key,
                "expected": expected,
                "actual": actual,
                "reason": (
                    "Stable transport safety matrix must remain clean, read-only, "
                    "non-executable, and free of direct approval markers."
                ),
            }
        )

    check_count = data.get("check_count")
    checks = data.get("checks")
    if not (type(check_count) is int and check_count > 0):
        result["field_drift_count"] += 1
        result["violations"].append(
            {
                "id": "transport-safety-matrix-check-count-invalid",
                "artifact": json_path.name,
                "json_path": "check_count",
                "reason": (
                    "Stable transport safety matrix must publish a positive integer "
                    "check_count."
                ),
                "actual": check_count,
            }
        )
    if not isinstance(checks, list):
        result["field_drift_count"] += 1
        result["violations"].append(
            {
                "id": "transport-safety-matrix-checks-invalid",
                "artifact": json_path.name,
                "json_path": "checks",
                "reason": "Stable transport safety matrix must publish a checks list.",
            }
        )
    elif type(check_count) is int and len(checks) != check_count:
        result["field_drift_count"] += 1
        result["violations"].append(
            {
                "id": "transport-safety-matrix-check-list-count-drift",
                "artifact": json_path.name,
                "json_path": "checks",
                "reason": (
                    "Stable transport safety matrix check_count does not match the "
                    "checks list length."
                ),
                "check_count": check_count,
                "checks_length": len(checks),
            }
        )
    failed_check_ids = (
        data.get("failed_check_ids") if isinstance(data.get("failed_check_ids"), list) else []
    )
    if failed_check_ids:
        result["field_drift_count"] += 1
        result["violations"].append(
            {
                "id": "transport-safety-matrix-failed-checks-present",
                "artifact": json_path.name,
                "json_path": "failed_check_ids",
                "reason": (
                    "Stable transport safety matrix lists failed transport checks."
                ),
                "failed_check_ids": failed_check_ids,
            }
        )

    expected_markdown_keys = [
        "status",
        "read_only",
        "live_revit_touched",
        "completion_allowed",
        "may_call_update_goal",
        "audit_completion_authorized",
        "may_execute_from_this_result",
        "check_count",
        "passed_count",
        "failed_count",
        "direct_approval_marker_count",
    ]
    expected_lines = [
        f"- {key}: `{str(data.get(key)).lower()}`"
        for key in expected_markdown_keys
        if key in data
    ]
    result["expected_markdown_line_count"] = len(expected_lines)
    result["missing_markdown_lines"] = []
    if not markdown_path.exists():
        result["markdown_present"] = False
        result["markdown_missing_line_count"] = len(expected_lines)
        result["violations"].append(
            {
                "id": "transport-safety-matrix-markdown-missing",
                "artifact": markdown_path.name,
                "source_artifact": json_path.name,
                "reason": (
                    "Stable transport safety matrix Markdown is missing, so the "
                    "human-readable transport safety status cannot be verified."
                ),
            }
        )
    else:
        try:
            markdown_text = markdown_path.read_text(encoding="utf-8")
        except OSError as exc:
            result["violations"].append(
                {
                    "id": "transport-safety-matrix-markdown-unreadable",
                    "artifact": markdown_path.name,
                    "source_artifact": json_path.name,
                    "reason": (
                        "Stable transport safety matrix Markdown could not be read: "
                        f"{type(exc).__name__}: {exc}"
                    ),
                    "path": str(markdown_path),
                }
            )
        else:
            markdown_marker_count = len(
                re.findall(r"\bAPPROVE:[A-Za-z0-9_.:-]+\b", markdown_text)
            ) + len(re.findall(r"\bI approve\b", markdown_text, flags=re.IGNORECASE))
            if markdown_marker_count:
                result["violations"].append(
                    {
                        "id": "transport-safety-matrix-markdown-approval-marker-leak",
                        "artifact": markdown_path.name,
                        "source_artifact": json_path.name,
                        "reason": (
                            "Stable transport safety matrix Markdown contains direct "
                            "approval markers."
                        ),
                        "marker_count": markdown_marker_count,
                    }
                )
            missing_lines = [
                line for line in expected_lines if line not in markdown_text
            ]
            result["missing_markdown_lines"] = missing_lines
            result["markdown_missing_line_count"] = len(missing_lines)
            if missing_lines:
                result["violations"].append(
                    {
                        "id": "transport-safety-matrix-markdown-drift",
                        "artifact": markdown_path.name,
                        "source_artifact": json_path.name,
                        "reason": (
                            "Stable transport safety matrix Markdown does not mirror "
                            "the JSON transport safety and authority fields."
                        ),
                        "missing_lines": missing_lines,
                    }
                )

    if result["violations"]:
        result["status"] = "violations"
        result["reason"] = "Stable transport safety matrix guard violations were found."
    else:
        result["status"] = "clean"
        result["reason"] = (
            "Stable transport safety matrix is clean, read-only, non-executable, "
            "credential-free, and mirrored in Markdown."
        )
    return result


def _human_unblock_brief_redaction_report(sandbox: Path) -> dict:
    json_path = sandbox / "NORTH_STAR_HUMAN_UNBLOCK_BRIEF_CURRENT.json"
    markdown_path = sandbox / "NORTH_STAR_HUMAN_UNBLOCK_BRIEF_CURRENT.md"
    result = {
        "status": "not_available",
        "reason": "No stable human unblock brief is present.",
        "artifact": json_path.name,
        "path": str(json_path),
        "markdown_artifact": markdown_path.name,
        "markdown_path": str(markdown_path),
        "present": json_path.exists(),
        "markdown_present": markdown_path.exists(),
        "json_parse_ok": None,
        "approval_option_count": 0,
        "direct_approval_marker_count": 0,
        "inconsistent_withheld_count": 0,
        "option_material_leak_count": 0,
        "violations": [],
    }
    if not json_path.exists() and not markdown_path.exists():
        return result
    if not json_path.exists():
        result["status"] = "violations"
        result["reason"] = "Human unblock brief Markdown exists without JSON."
        result["violations"].append(
            {
                "id": "human-unblock-brief-json-missing",
                "artifact": json_path.name,
                "markdown_artifact": markdown_path.name,
                "reason": (
                    "Stable human unblock brief Markdown is present, but the "
                    "machine-readable JSON artifact is missing."
                ),
            }
        )
        return result

    try:
        raw_text = json_path.read_text(encoding="utf-8")
        data = json.loads(raw_text)
    except (OSError, json.JSONDecodeError) as exc:
        result["status"] = "violations"
        result["reason"] = "Human unblock brief JSON could not be parsed."
        result["json_parse_ok"] = False
        result["violations"].append(
            {
                "id": "human-unblock-brief-unreadable",
                "artifact": json_path.name,
                "reason": (
                    "Stable human unblock brief JSON could not be parsed: "
                    f"{type(exc).__name__}: {exc}"
                ),
                "path": str(json_path),
            }
        )
        return result
    if not isinstance(data, dict):
        result["status"] = "violations"
        result["reason"] = "Human unblock brief JSON is not an object."
        result["json_parse_ok"] = True
        result["violations"].append(
            {
                "id": "human-unblock-brief-invalid",
                "artifact": json_path.name,
                "reason": "Stable human unblock brief JSON is not a JSON object.",
                "path": str(json_path),
            }
        )
        return result

    result["json_parse_ok"] = True
    raw_marker_count = len(re.findall(r"\bAPPROVE:[A-Za-z0-9_.:-]+\b", raw_text)) + len(
        re.findall(r"\bI approve\b", raw_text, flags=re.IGNORECASE)
    )
    result["direct_approval_marker_count"] = raw_marker_count
    if raw_marker_count:
        result["violations"].append(
            {
                "id": "human-unblock-brief-approval-marker-leak",
                "artifact": json_path.name,
                "reason": (
                    "Stable human unblock brief JSON contains direct approval "
                    "markers; regenerate the redacted brief."
                ),
                "marker_count": raw_marker_count,
            }
        )

    if data.get("approval_material_included") is not False:
        result["violations"].append(
            {
                "id": "human-unblock-brief-approval-material-included-drift",
                "artifact": json_path.name,
                "json_path": "approval_material_included",
                "reason": (
                    "Stable human unblock brief must explicitly publish "
                    "approval_material_included: false."
                ),
                "actual": data.get("approval_material_included"),
            }
        )
    if (
        data.get("approval_material_present_in_source") is True
        and data.get("approval_material_withheld") is not True
    ):
        result["inconsistent_withheld_count"] += 1
        result["violations"].append(
            {
                "id": "human-unblock-brief-top-level-withheld-drift",
                "artifact": json_path.name,
                "json_path": "approval_material_withheld",
                "reason": (
                    "Stable human unblock brief detected approval material in the "
                    "source but does not clearly mark that material as withheld."
                ),
                "actual": data.get("approval_material_withheld"),
            }
        )

    options = data.get("sanitized_options") if isinstance(data.get("sanitized_options"), list) else []
    for index, option in enumerate(options):
        if not isinstance(option, dict):
            continue
        is_approval_option = (
            option.get("kind") == "human_approval"
            or option.get("approval_phrase_available_in_source") is True
            or option.get("approval_material_available_in_source") is True
        )
        if is_approval_option:
            result["approval_option_count"] += 1
        if option.get("approval_material_included") is not False:
            result["option_material_leak_count"] += 1
            result["violations"].append(
                {
                    "id": "human-unblock-option-approval-material-included-drift",
                    "artifact": json_path.name,
                    "json_path": f"sanitized_options[{index}].approval_material_included",
                    "option_id": option.get("id"),
                    "reason": (
                        "Every human unblock option must explicitly mark approval "
                        "material as omitted from the sanitized brief."
                    ),
                    "actual": option.get("approval_material_included"),
                }
            )
        if is_approval_option and option.get("approval_material_withheld") is not True:
            result["inconsistent_withheld_count"] += 1
            result["violations"].append(
                {
                    "id": "human-unblock-option-approval-material-withheld-drift",
                    "artifact": json_path.name,
                    "json_path": f"sanitized_options[{index}].approval_material_withheld",
                    "option_id": option.get("id"),
                    "reason": (
                        "Approval-related human unblock options must clearly mark "
                        "their approval material as withheld."
                    ),
                    "actual": option.get("approval_material_withheld"),
                }
            )
        if (
            option.get("approval_phrase_available_in_source") is True
            and option.get("required_human_approval_phrase_withheld") is not True
        ):
            result["inconsistent_withheld_count"] += 1
            result["violations"].append(
                {
                    "id": "human-unblock-option-phrase-withheld-drift",
                    "artifact": json_path.name,
                    "json_path": (
                        f"sanitized_options[{index}]."
                        "required_human_approval_phrase_withheld"
                    ),
                    "option_id": option.get("id"),
                    "reason": (
                        "If a source approval phrase exists, the sanitized brief "
                        "must mark the phrase as withheld."
                    ),
                    "actual": option.get("required_human_approval_phrase_withheld"),
                }
            )
        if "required_human_approval_phrase" in option or "approval_token" in option:
            result["option_material_leak_count"] += 1
            result["violations"].append(
                {
                    "id": "human-unblock-option-raw-approval-field-present",
                    "artifact": json_path.name,
                    "json_path": f"sanitized_options[{index}]",
                    "option_id": option.get("id"),
                    "reason": (
                        "Sanitized human unblock options must not retain raw "
                        "approval phrase or token fields."
                    ),
                }
            )

    if not markdown_path.exists():
        result["violations"].append(
            {
                "id": "human-unblock-brief-markdown-missing",
                "artifact": markdown_path.name,
                "source_artifact": json_path.name,
                "reason": (
                    "Stable human unblock brief Markdown is missing, so the "
                    "human-readable redaction state cannot be verified."
                ),
            }
        )
    else:
        try:
            markdown_text = markdown_path.read_text(encoding="utf-8")
        except OSError as exc:
            result["violations"].append(
                {
                    "id": "human-unblock-brief-markdown-unreadable",
                    "artifact": markdown_path.name,
                    "source_artifact": json_path.name,
                    "reason": (
                        "Stable human unblock brief Markdown could not be read: "
                        f"{type(exc).__name__}: {exc}"
                    ),
                    "path": str(markdown_path),
                }
            )
        else:
            markdown_marker_count = len(
                re.findall(r"\bAPPROVE:[A-Za-z0-9_.:-]+\b", markdown_text)
            ) + len(re.findall(r"\bI approve\b", markdown_text, flags=re.IGNORECASE))
            if markdown_marker_count:
                result["violations"].append(
                    {
                        "id": "human-unblock-brief-markdown-approval-marker-leak",
                        "artifact": markdown_path.name,
                        "source_artifact": json_path.name,
                        "reason": (
                            "Stable human unblock brief Markdown contains direct "
                            "approval markers."
                        ),
                        "marker_count": markdown_marker_count,
                    }
                )
            required_lines = [
                "- approval_material_included: `false`",
                f"- approval_material_withheld: `{str(data.get('approval_material_withheld')).lower()}`",
            ]
            missing_lines = [line for line in required_lines if line not in markdown_text]
            if missing_lines:
                result["violations"].append(
                    {
                        "id": "human-unblock-brief-markdown-redaction-drift",
                        "artifact": markdown_path.name,
                        "source_artifact": json_path.name,
                        "reason": (
                            "Stable human unblock brief Markdown does not mirror "
                            "the top-level approval redaction fields."
                        ),
                        "missing_lines": missing_lines,
                    }
                )

    if result["violations"]:
        result["status"] = "violations"
        result["reason"] = "Stable human unblock brief redaction violations were found."
    else:
        result["status"] = "clean"
        result["reason"] = (
            "Stable human unblock brief omits direct approval material and marks "
            "approval-related options as withheld."
        )
    return result


def _unblock_readiness_refresh_command_report(sandbox: Path) -> dict:
    path = sandbox / "NORTH_STAR_UNBLOCK_READINESS_CURRENT.json"
    result = {
        "status": "not_available",
        "reason": "No stable unblock-readiness JSON is present.",
        "artifact": path.name,
        "path": str(path),
        "command_count": 0,
        "packet_command_count": 0,
        "context_source_path": None,
        "context_source_available": False,
        "expected_context": {},
        "commands": [],
        "violations": [],
    }
    if not path.exists():
        return result

    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        result["status"] = "violations"
        result["reason"] = "Stable unblock-readiness JSON could not be parsed."
        result["violations"].append(
            {
                "id": "unblock-readiness-refresh-command-artifact-unreadable",
                "artifact": path.name,
                "reason": (
                    "Stable unblock-readiness JSON could not be parsed: "
                    f"{type(exc).__name__}: {exc}"
                ),
                "path": str(path),
            }
        )
        return result

    context = _completion_gate_expected_context(sandbox)
    expected_context = _refresh_command_expected_context(context)
    result["context_source_path"] = context.get("path")
    result["context_source_available"] = context.get("available") is True
    result["expected_context"] = expected_context

    artifact_readiness = (
        data.get("artifact_readiness")
        if isinstance(data.get("artifact_readiness"), dict)
        else {}
    )
    command_specs: list[dict] = [
        {
            "source": "artifact_readiness",
            "json_path": "artifact_readiness.safe_supervision_refresh_command",
            "command": artifact_readiness.get("safe_supervision_refresh_command"),
            "powershell": artifact_readiness.get("safe_supervision_refresh_powershell"),
            "read_only": artifact_readiness.get("safe_supervision_refresh_read_only"),
        }
    ]
    autonomous_stop = (
        data.get("autonomous_stop")
        if isinstance(data.get("autonomous_stop"), dict)
        else {}
    )
    if autonomous_stop:
        command_specs.append(
            {
                "source": "autonomous_stop",
                "json_path": "autonomous_stop.safe_refresh_command",
                "command": autonomous_stop.get("safe_refresh_command"),
                "powershell": autonomous_stop.get("safe_refresh_powershell"),
                "read_only": autonomous_stop.get("safe_refresh_read_only"),
            }
        )
    blocker_packets = (
        data.get("blocker_readiness")
        if isinstance(data.get("blocker_readiness"), list)
        else []
    )
    for index, packet in enumerate(blocker_packets):
        if not isinstance(packet, dict):
            continue
        command_specs.append(
            {
                "source": f"blocker_readiness[{index}]",
                "gap_id": packet.get("gap_id"),
                "json_path": f"blocker_readiness[{index}].safe_supervision_refresh_command",
                "command": packet.get("safe_supervision_refresh_command"),
                "powershell": packet.get("safe_supervision_refresh_powershell"),
                "read_only": packet.get("safe_supervision_refresh_read_only"),
            }
        )

    baseline_command: list[str] | None = None
    for spec in command_specs:
        source_violations, command = _safe_refresh_command_violations(
            artifact=path.name,
            spec=spec,
            expected_context=expected_context,
        )
        if command is not None:
            result["command_count"] += 1
            if spec["source"].startswith("blocker_readiness["):
                result["packet_command_count"] += 1
            result["commands"].append(
                {
                    "source": spec["source"],
                    "gap_id": spec.get("gap_id"),
                    "json_path": spec["json_path"],
                    "command": command,
                    "powershell": spec.get("powershell"),
                }
            )
            if spec["source"] == "artifact_readiness":
                baseline_command = command
            elif baseline_command is not None and command != baseline_command:
                source_violations.append(
                    {
                        "id": "unblock-readiness-refresh-command-packet-drift",
                        "artifact": path.name,
                        "json_path": spec["json_path"],
                        "gap_id": spec.get("gap_id"),
                        "reason": (
                            "A blocker packet refresh command differs from the "
                            "artifact_readiness refresh command."
                        ),
                    }
                )
        result["violations"].extend(source_violations)

    if result["violations"]:
        result["status"] = "violations"
        result["reason"] = (
            "Stable unblock-readiness refresh commands are missing, executable, "
            "or no longer match the latest expected Revit context."
        )
    else:
        result["status"] = "ok"
        result["reason"] = (
            "Stable unblock-readiness refresh commands are read-only, "
            "context-matched, and non-executable."
        )
    return result


def _unblock_readiness_stable_scan_mirror_report(sandbox: Path) -> dict:
    """Check that unblock-readiness mirrors the current stable scan status."""

    unblock_path = sandbox / "NORTH_STAR_UNBLOCK_READINESS_CURRENT.json"
    scan_path = sandbox / "NORTH_STAR_STABLE_ARTIFACT_SCAN_CURRENT.json"
    result = {
        "status": "not_available",
        "reason": "No stable unblock-readiness JSON is present.",
        "artifact": unblock_path.name,
        "path": str(unblock_path),
        "source_artifact": scan_path.name,
        "source_path": str(scan_path),
        "unblock_available": False,
        "stable_scan_available": False,
        "mismatches": [],
        "mismatch_count": 0,
        "optimistic_mismatches": [],
        "optimistic_mismatch_count": 0,
        "pessimistic_mismatches": [],
        "pessimistic_mismatch_count": 0,
        "violations": [],
    }
    if not unblock_path.exists():
        return result

    try:
        unblock = json.loads(unblock_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        result["status"] = "violations"
        result["reason"] = "Stable unblock-readiness JSON could not be parsed."
        result["violations"].append(
            {
                "id": "unblock-readiness-stable-scan-mirror-unreadable",
                "artifact": unblock_path.name,
                "reason": (
                    "Stable unblock-readiness JSON could not be parsed for stable-scan "
                    f"mirror validation: {type(exc).__name__}: {exc}"
                ),
                "path": str(unblock_path),
            }
        )
        return result
    if not isinstance(unblock, dict):
        result["status"] = "violations"
        result["reason"] = "Stable unblock-readiness JSON is not an object."
        result["violations"].append(
            {
                "id": "unblock-readiness-stable-scan-mirror-unreadable",
                "artifact": unblock_path.name,
                "reason": "Stable unblock-readiness JSON is not an object.",
                "path": str(unblock_path),
            }
        )
        return result

    result["unblock_available"] = True
    if not scan_path.exists():
        actual_available = False
        actual_status = None
        actual_violation_count = None
    else:
        try:
            stable_scan = json.loads(scan_path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError) as exc:
            result["status"] = "violations"
            result["reason"] = "Stable scan current JSON could not be parsed."
            result["violations"].append(
                {
                    "id": "unblock-readiness-stable-scan-source-unreadable",
                    "artifact": unblock_path.name,
                    "source_artifact": scan_path.name,
                    "reason": (
                        "Stable scan current JSON could not be parsed for "
                        f"unblock-readiness mirror validation: {type(exc).__name__}: {exc}"
                    ),
                    "source_path": str(scan_path),
                }
            )
            return result
        if not isinstance(stable_scan, dict):
            result["status"] = "violations"
            result["reason"] = "Stable scan current JSON is not an object."
            result["violations"].append(
                {
                    "id": "unblock-readiness-stable-scan-source-unreadable",
                    "artifact": unblock_path.name,
                    "source_artifact": scan_path.name,
                    "reason": "Stable scan current JSON is not an object.",
                    "source_path": str(scan_path),
                }
            )
            return result
        actual_available = True
        actual_status = stable_scan.get("status")
        actual_violation_count = stable_scan.get("violation_count")

    result["stable_scan_available"] = actual_available
    artifact_readiness = (
        unblock.get("artifact_readiness")
        if isinstance(unblock.get("artifact_readiness"), dict)
        else {}
    )
    current_artifacts = (
        unblock.get("current_artifacts")
        if isinstance(unblock.get("current_artifacts"), dict)
        else {}
    )
    current_scan = (
        current_artifacts.get("stable_artifact_scan")
        if isinstance(current_artifacts.get("stable_artifact_scan"), dict)
        else {}
    )
    expected_clean = actual_violation_count == 0 if actual_available else False
    checks = [
        (
            "artifact_readiness.stable_artifact_scan_present",
            artifact_readiness.get("stable_artifact_scan_present"),
            actual_available,
        ),
        (
            "artifact_readiness.stable_artifact_scan_clean",
            artifact_readiness.get("stable_artifact_scan_clean"),
            expected_clean,
        ),
        (
            "current_artifacts.stable_artifact_scan.available",
            current_scan.get("available"),
            actual_available,
        ),
        (
            "current_artifacts.stable_artifact_scan.status",
            current_scan.get("status"),
            actual_status,
        ),
        (
            "current_artifacts.stable_artifact_scan.violation_count",
            current_scan.get("violation_count"),
            actual_violation_count,
        ),
    ]
    mismatches = [
        {
            "field": field,
            "unblock_value": unblock_value,
            "stable_scan_value": stable_value,
        }
        for field, unblock_value, stable_value in checks
        if unblock_value != stable_value
    ]
    optimistic_mismatches = []
    pessimistic_mismatches = []
    for item in mismatches:
        field = item["field"]
        unblock_value = item["unblock_value"]
        stable_value = item["stable_scan_value"]
        optimistic = False
        if field.endswith("stable_artifact_scan_present") or field.endswith(
            "stable_artifact_scan.available"
        ):
            optimistic = unblock_value is True and stable_value is False
        elif field.endswith("stable_artifact_scan_clean"):
            optimistic = unblock_value is True and stable_value is False
        elif field.endswith("stable_artifact_scan.status"):
            optimistic = unblock_value == "clean" and stable_value != "clean"
        elif field.endswith("stable_artifact_scan.violation_count"):
            optimistic = (
                isinstance(unblock_value, int)
                and isinstance(stable_value, int)
                and unblock_value < stable_value
            )
        if optimistic:
            optimistic_mismatches.append(item)
        else:
            pessimistic_mismatches.append(item)
    result["mismatches"] = mismatches
    result["mismatch_count"] = len(mismatches)
    result["optimistic_mismatches"] = optimistic_mismatches
    result["optimistic_mismatch_count"] = len(optimistic_mismatches)
    result["pessimistic_mismatches"] = pessimistic_mismatches
    result["pessimistic_mismatch_count"] = len(pessimistic_mismatches)
    if optimistic_mismatches:
        result["status"] = "violations"
        result["reason"] = (
            "Stable unblock-readiness artifact is more permissive than the current "
            "stable scan status."
        )
        result["violations"].append(
            {
                "id": "unblock-readiness-stable-scan-optimistic-mirror-drift",
                "artifact": unblock_path.name,
                "source_artifact": scan_path.name,
                "reason": (
                    "Stable unblock-readiness embeds stale or incorrect stable scan "
                    "status/count fields that understate current scan risk."
                ),
                "mismatches": optimistic_mismatches,
                "path": str(unblock_path),
                "source_path": str(scan_path),
            }
        )
    elif pessimistic_mismatches:
        result["status"] = "ok_with_pessimistic_drift"
        result["reason"] = (
            "Stable unblock-readiness is stale but more conservative than the current "
            "stable scan; rerun the read-only watch refresh to update the handoff."
        )
    else:
        result["status"] = "ok"
        result["reason"] = "Stable unblock-readiness mirrors the current stable scan."
    return result


def _next_human_options_summary_snapshot(data: dict) -> dict:
    options = data.get("next_human_options") if isinstance(data.get("next_human_options"), list) else []
    option_ids = data.get("option_ids")
    if not isinstance(option_ids, list):
        option_ids = [
            str(item.get("id"))
            for item in options
            if isinstance(item, dict) and item.get("id")
        ]
    option_ids = [str(item) for item in option_ids if str(item or "").strip()]
    summaries = data.get("option_summaries")
    if not isinstance(summaries, list):
        summaries = _next_human_option_summaries(options)
    summaries = [item for item in summaries if isinstance(item, dict)]
    option_count = data.get("option_count")
    if not isinstance(option_count, int):
        option_count = len(option_ids)
    return {
        "option_count": option_count,
        "option_ids": option_ids,
        "option_summaries": summaries,
    }


def _unblock_next_human_options_summary_snapshot(data: dict) -> dict:
    option_ids = data.get("next_human_option_ids")
    if not isinstance(option_ids, list):
        option_ids = []
    option_ids = [str(item) for item in option_ids if str(item or "").strip()]
    summaries = data.get("next_human_option_summaries")
    if not isinstance(summaries, list):
        summaries = []
    summaries = [item for item in summaries if isinstance(item, dict)]
    option_count = data.get("next_human_option_count")
    if not isinstance(option_count, int):
        option_count = len(option_ids)
    return {
        "option_count": option_count,
        "option_ids": option_ids,
        "option_summaries": summaries,
    }


def _option_summary_contains_credential_material(summary: dict) -> bool:
    text = json.dumps(summary, sort_keys=True, default=str)
    return bool(
        re.search(r"\bAPPROVE:[A-Za-z0-9_.:-]+\b", text)
        or re.search(r"\bI approve\b", text, re.IGNORECASE)
        or "required_human_approval_phrase" in summary
        or "approval_token" in summary
    )


def _handoff_next_human_options_mirror_report(sandbox: Path) -> dict:
    handoff_path = sandbox / "NORTH_STAR_HANDOFF_CURRENT.json"
    next_human_path = sandbox / "NORTH_STAR_NEXT_HUMAN_ACTION_CURRENT.json"
    result = {
        "status": "not_available",
        "reason": "No stable current handoff JSON is present.",
        "artifact": handoff_path.name,
        "path": str(handoff_path),
        "source_artifact": next_human_path.name,
        "source_path": str(next_human_path),
        "handoff_available": False,
        "next_human_available": False,
        "mismatches": [],
        "mismatch_count": 0,
        "credential_leaks": [],
        "credential_leak_count": 0,
        "violations": [],
    }
    if not handoff_path.exists():
        return result
    try:
        handoff = json.loads(handoff_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        result["status"] = "violations"
        result["reason"] = "Stable current handoff JSON could not be parsed."
        result["violations"].append(
            {
                "id": "handoff-next-human-options-mirror-unreadable",
                "artifact": handoff_path.name,
                "reason": (
                    "Stable current handoff JSON could not be parsed for "
                    f"next-human option mirror validation: {type(exc).__name__}: {exc}"
                ),
                "path": str(handoff_path),
            }
        )
        return result
    if not isinstance(handoff, dict):
        result["status"] = "violations"
        result["reason"] = "Stable current handoff JSON is not an object."
        result["violations"].append(
            {
                "id": "handoff-next-human-options-mirror-unreadable",
                "artifact": handoff_path.name,
                "reason": "Stable current handoff JSON is not an object.",
                "path": str(handoff_path),
            }
        )
        return result
    result["handoff_available"] = True
    handoff_next_human = (
        handoff.get("next_human_action")
        if isinstance(handoff.get("next_human_action"), dict)
        else {}
    )
    if not next_human_path.exists():
        source = {"option_count": 0, "option_ids": [], "option_summaries": []}
    else:
        try:
            next_human = json.loads(next_human_path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError) as exc:
            result["status"] = "violations"
            result["reason"] = "Stable next-human-action JSON could not be parsed."
            result["violations"].append(
                {
                    "id": "handoff-next-human-options-source-unreadable",
                    "artifact": handoff_path.name,
                    "source_artifact": next_human_path.name,
                    "reason": (
                        "Stable next-human-action JSON could not be parsed for "
                        f"current handoff option mirror validation: {type(exc).__name__}: {exc}"
                    ),
                    "source_path": str(next_human_path),
                }
            )
            return result
        if not isinstance(next_human, dict):
            result["status"] = "violations"
            result["reason"] = "Stable next-human-action JSON is not an object."
            result["violations"].append(
                {
                    "id": "handoff-next-human-options-source-unreadable",
                    "artifact": handoff_path.name,
                    "source_artifact": next_human_path.name,
                    "reason": "Stable next-human-action JSON is not an object.",
                    "source_path": str(next_human_path),
                }
            )
            return result
        result["next_human_available"] = True
        source = _next_human_options_summary_snapshot(next_human)

    mirror = _next_human_options_summary_snapshot(handoff_next_human)
    checks = [
        ("next_human_action.option_count", mirror["option_count"], source["option_count"]),
        ("next_human_action.option_ids", mirror["option_ids"], source["option_ids"]),
        (
            "next_human_action.option_summaries",
            mirror["option_summaries"],
            source["option_summaries"],
        ),
    ]
    mismatches = [
        {
            "field": field,
            "handoff_value": handoff_value,
            "next_human_value": next_human_value,
        }
        for field, handoff_value, next_human_value in checks
        if handoff_value != next_human_value
    ]
    leaks = [
        {
            "field": f"next_human_action.option_summaries.{index}",
            "id": item.get("id"),
            "reason": (
                "Current handoff next-human option summaries must not expose "
                "approval tokens or exact approval phrases."
            ),
        }
        for index, item in enumerate(mirror["option_summaries"])
        if _option_summary_contains_credential_material(item)
    ]
    result["mismatches"] = mismatches
    result["mismatch_count"] = len(mismatches)
    result["credential_leaks"] = leaks
    result["credential_leak_count"] = len(leaks)
    if mismatches:
        result["violations"].append(
            {
                "id": "handoff-next-human-options-mirror-drift",
                "artifact": handoff_path.name,
                "source_artifact": next_human_path.name,
                "reason": (
                    "Stable current handoff next-human option summaries drift "
                    "from the stable next-human-action artifact."
                ),
                "mismatches": mismatches,
                "path": str(handoff_path),
                "source_path": str(next_human_path),
            }
        )
    if leaks:
        result["violations"].append(
            {
                "id": "handoff-next-human-options-credential-leak",
                "artifact": handoff_path.name,
                "reason": (
                    "Stable current handoff next-human option summaries expose "
                    "approval credential material."
                ),
                "credential_leaks": leaks,
                "path": str(handoff_path),
            }
        )
    if result["violations"]:
        result["status"] = "violations"
        result["reason"] = "Stable current handoff next-human option summaries are unsafe or stale."
    else:
        result["status"] = "ok"
        result["reason"] = "Stable current handoff mirrors next-human option summaries."
    return result


